	["tid#first_name1"]="少侠",
	["tid#VersionMsg_1"]="当前客户端版本过低，请下载新客户端",
	["tid#WorldBossCycle_1"]="玄武遗迹的描述",
	["tid#WorldBossCycleAlert_1"]="内伤免疫",
	["tid#WorldBossCycleAlertDes_1"]="此首领免疫所有内伤攻击",
	["tid#WorldBossCycle_2"]="玄武遗迹的描述",
	["tid#WorldBossCycleAlert_2"]="外伤免疫",
	["tid#WorldBossCycleAlertDes_2"]="此首领免疫所有外伤攻击",
	["tid#GuideDes_1"]="猖狂之徒，先和我打一场再说！",
	["tid#GuideDes_2"]="点击头像，让胡大壮上阵吧。",
	["tid#GuideDes_3"]="惩奸除恶，怎么少得了我！让我和你们并肩战斗！",
	["tid#GuideDes_4"]="放马过来吧！",
	["tid#GuideDes_5"]="让你见识一下我的绝技！",
	["tid#GuideDes_6"]="先继续向前查探吧。",
	["tid#GuideDes_7"]="我也来帮忙！",
	["tid#GuideDes_8"]="我擅长伺机而动、从旁攻击，就暂且站在后面了~",
	["tid#GuideDes_9"]="我们齐心协力，一定能击退敌人！",
	["tid#GuideDes_10"]="点击“侠客”按钮，来提升侠客的实力。",
	["tid#GuideDes_11"]="选择一个侠客，让他变强吧。",
	["tid#GuideDes_12"]="点击升级按钮可以提升侠客的等级。",
	["tid#GuideDes_13"]="点击这里，就能为侠客穿上最强的装备。",
	["tid#GuideDes_14"]="少侠，我们似乎变强了很多呢~",
	["tid#GuideDes_15"]="继续回到刚才的战场吧。",
	["tid#GuideDes_16"]="整备完毕，继续战斗吧！",
	["tid#GuideDes_17"]="点击我的头像，让我加入战斗",
	["tid#GuideDes_18"]="接下来就交给你来指挥了，试试看吧。",
	["tid#GuideDes_19"]="快去看看我们能找到哪位帮手",
	["tid#GuideDes_20"]="点击这里，前往招募",
	["tid#GuideDes_21"]="就是这里了，快去看看究竟是谁在等着我们吧。",
	["tid#GuideDes_22"]="是一位厉害的侠客，我们来让他提升一下吧！",
	["tid#GuideDes_23"]="接下来就交给你了，继续努力吧。",
	["tid#GuideDes_24"]="开始战斗吧，这次一定万无一失。",
	["tid#GuideDes_25"]="少侠，我们先离开吧。",
	["tid#GuideDes_26"]="这里是我们平日游历的积蓄，以备不时之需。",
	["tid#GuideDes_27"]="少侠可于必要之时将它打开，取出其中物资。",
	["tid#GuideDes_28"]="点击“侠客”，去强化队伍吧。",
	["tid#GuideDes_29"]="点击侠客选择一位侠客",
	["tid#GuideDes_30"]="“升级”的操作，你应该还没忘吧。",
	["tid#GuideDes_31"]="不错，这下就更有信心了。",
	["tid#GuideDes_32"]="返回刚才的战场吧。",
	["tid#GuideDes_33"]="继续任务吧，这次一定不会再失败了。",
	["tid#GuideDes_34"]="点击这里，返回挂机界面。",
	["tid#GuideDes_35"]="这是快速挂机按钮，点击后立刻获得两个小时的挂机收益。",
	["tid#GuideDes_36"]="少侠不用担心，每天都有一次免费领取的机会。",
	["tid#GuideDes_37"]="奖励领取完毕，快去提升队伍的实力吧",
	["tid#GuideDes_38"]="点击这里，返回挂机界面。",
	["tid#GuideDes_39"]="点击这里，去往研习界面。",
	["tid#GuideDes_40"]="点击这里，前往练武场",
	["tid#GuideDes_41"]="初始只有两个栏位，消耗元宝可以解锁更多栏位。",
	["tid#GuideDes_42"]="就让这位大侠先来试试吧！",
	["tid#GuideDes_43"]="点击确定按钮",
	["tid#GuideDes_44"]="点击返回",
	["tid#GuideDes_45"]="点击这里，返回挂机界面。",
	["tid#GuideDes_46"]="点击这里，去往研习界面。",
	["tid#GuideDes_47"]="点击这里，去往传功殿。",
