	["tid#GuideDes_49"]="在这里可以为传功做一些准备。",
	["tid#GuideDes_50"]="凑齐材料后，点击这里就能升阶了。",
	["tid#GuideDes_51"]="开始传功，侠客就能变强啦。",
	["tid#GuideDes_52"]="关闭进阶动画",
