	["tid#GuideDes_68"]="点击这里，返回挂机界面。",
	["tid#GuideDes_69"]="点击这里，前往江湖地图",
	["tid#GuideDes_70"]="点击这里，前往四象阵。",
	["tid#GuideDes_71"]="当前楼层的奖励信息会展示在这里。",
	["tid#GuideDes_72"]="先从这个敌人开始吧！",
	["tid#GuideDes_73"]="点击这里，返回挂机界面。",
	["tid#GuideDes_74"]="点击这里，前往论剑地图",
	["tid#GuideDes_75"]="点击这里，前往论剑山庄。",
	["tid#GuideDes_76"]="点击挑战按钮",
	["tid#GuideDes_77"]="点击刷新",
	["tid#GuideDes_78"]="点击返回",
	["tid#GuideDes_79"]="点击防御按钮",
	["tid#GuideDes_80"]="引导手指向侠客列表（弱）",
	["tid#GuideDes_81"]="引导手指向保存编队（弱）",
	["tid#GuideDes_82"]="点击这里，返回挂机界面。",
	["tid#GuideDes_83"]="点击这里，前往江湖地图。",
	["tid#GuideDes_84"]="点击这里，前往悬赏",
	["tid#GuideDes_85"]="点击“派遣”，选择一个任务。",
	["tid#GuideDes_86"]="点击上阵栏位，即可指派侠客前往。",
	["tid#GuideDes_87"]="空闲中的侠客都会显示在这里。",
	["tid#GuideDes_88"]="任务的需求会展示在这里。",
	["tid#GuideDes_89"]="你就是新来的帮手吗？",
	["tid#GuideDes_90"]="看起来还算有点样子，就是不知道身手如何。",
	["tid#GuideDes_91"]="正好，我们刚接到一个小任务，你也跟上来吧。",
	["tid#GuideDes_92"]="神刀，我把人带来了。",
	["tid#GuideDes_93"]="总算来了吗？我都等的不耐烦了，赶紧开始任务吧。",
	["tid#GuideDes_94"]="头场战斗就让我来吧，新来的小家伙就先在边上看一看，学着点。",
	["tid#GuideDes_95"]="这些家伙还挺难缠的，看来要动点真格的了。",
	["tid#GuideDes_96"]="神机？怎么才来？",
	["tid#GuideDes_97"]="路上遇到几个小虫子，耽误了点时间。",
	["tid#GuideDes_98"]="小虫子？不是你又惹了什么麻烦吧。",
	["tid#GuideDes_99"]="现在形势这么紧张，我们最好还是小心一点。",
	["tid#GuideDes_100"]="放心，几个不长眼的小喽啰而已，已经解决了。",
	["tid#GuideDes_101"]="好，既然人都到到齐了，那就继续吧。",
	["tid#GuideDes_102"]="敌人有点多，我也来帮忙吧。",
	["tid#GuideDes_103"]="也好，你们两个一起吧，速战速决。",
	["tid#GuideDes_104"]="怎么停下了？继续啊。",
	["tid#GuideDes_105"]="任务越来越凶险了，小心些，先回去整备一下。",
	["tid#GuideDes_106"]="刚才那些敌人逃走的匆忙，似乎遗落了一些装备。",
	["tid#GuideDes_107"]="虽然不是什么上品货色，但也能为队伍带来不错的实力提升，快装备上吧。",
	["tid#GuideDes_108"]="这次的敌人，似乎不好惹啊。",
	["tid#GuideDes_109"]="别担心，这次的战斗我也会上场。",
	["tid#GuideDes_110"]="任务结束，大家辛苦了。",
	["tid#GuideDes_111"]="怎么样？大家觉得如何？",
	["tid#GuideDes_112"]="虽然还有点稚嫩，不过，嗯……还凑合吧。",
	["tid#GuideDes_113"]="实力……尚可，为人……不错，处事……果决。我同意！",
	["tid#GuideDes_114"]="好，既然大家都没有意见，那么我宣布，你的测试通过了。",
	["tid#GuideDes_115"]="别那么惊讶了，小家伙，还没看出来吗？这场任务是我们对你的考验。",
	["tid#GuideDes_116"]="没错，恭喜你，考验通过了，从今天开始，你就是我们的一员了。",
	["tid#GuideDes_117"]="要加油啊，小家伙，可别让我失望。",
	["tid#GuideDes_118"]="加油，有任务随时来找我。",
	["tid#GuideDes_119"]="怎么闷闷不乐的，出什么事了吗？",
	["tid#GuideDes_120"]="任务失败？原来是这样。",
	["tid#GuideDes_121"]="胜负乃兵家常事，少侠也不用这么在意。",
	["tid#GuideDes_122"]="这样吧，少侠跟我来。",
	["tid#GuideDes_123"]="少侠可知道，平日里你不在的时候我们都在干什么？",
	["tid#GuideDes_124"]="即便是少侠不在，我们这些侠客也从来没有停止过战斗，通过战斗获得的奖励都储存在这里。",
	["tid#GuideDes_125"]="有了这些物资，队伍的实力一定会更上一层楼的。",
	["tid#GuideDes_126"]="提升队伍实力之后，再去挑战刚才的任务吧。",
	["tid#GuideDes_127"]="少侠，如今队伍已经稳定下来了，是时候做些更长远的打算了。",
	["tid#GuideDes_128"]="队伍想要发展，必定需要更多的人手，少侠觉得呢？",
	["tid#GuideDes_129"]="嗯，在下明白了，既然这样的话，少侠跟我来吧。",
	["tid#GuideDes_130"]="驻地中有一处建筑叫做聚义客栈，不知道少侠有没有见过。",
	["tid#GuideDes_131"]="在之前的大战中，这处建筑被破坏了，不久前才修好。",
	["tid#GuideDes_132"]="在聚义客栈中，少侠可以发布招募令，招募令发布之后，对我们感兴趣的侠客就会前来加入。",
	["tid#GuideDes_133"]="若是运气足够好，甚至能获得一些顶级侠客的青睐。",
	["tid#GuideDes_134"]="事不宜迟，我带少侠去看看吧。",
	["tid#GuideDes_135"]="少侠，是不是觉得最近队伍的实力增长缓慢？",
	["tid#GuideDes_136"]="我最近刚刚发现了一个小技巧，可以快速提升队伍的实力，来看看吧。",
	["tid#GuideDes_137"]="少侠，传功殿已经修复好了，我带你去看看吧。",
	["tid#GuideDes_138"]="这里就是传功殿了，在这里可以提升侠客的品阶。",
	["tid#GuideDes_139"]="品阶提升后，不仅能提高侠客的战斗属性，还能够提升侠客的最高等级，实力能够得到质的飞越。",
	["tid#GuideDes_140"]="我带你进去看看吧。",
	["tid#GuideDes_141"]="等一下少侠，我需要提醒你一下。",
	["tid#GuideDes_142"]="侠客升阶时，被当做材料的侠客会被消耗，可要小心别把强力的侠客当做材料用了。",
	["tid#GuideDes_143"]="每次升阶之前，一定要小心确认。",
	["tid#GuideDes_144"]="好了，我们继续吧。",
	["tid#GuideDes_145"]="少侠，有几位外出的侠客发现了一处秘境，一起去看看吧。",
	["tid#GuideDes_146"]="少侠，我们到了。",
	["tid#GuideDes_147"]="这处秘境叫做“闯王宝藏”，古籍中说，此地是一位大能建造的迷宫，里面遍布着危险和机遇。",
	["tid#GuideDes_148"]="小心些，我和你一起进去看看。",
	["tid#GuideDes_149"]="前面应该就是古籍上所说的宝藏守卫了，看起来很危险的样子。",
	["tid#GuideDes_150"]="击败这里的守卫，能够获得奇物和道具奖励。奇物只能在宝藏中使用，不过能为队伍提供极强的战力加成，",
	["tid#GuideDes_151"]="多说无益，少侠亲自来试一下吧。",
	["tid#GuideDes_152"]="这处建筑是援兵守卫，我们可以在此处招募强力侠客协助战斗，虽然只能在迷宫中使用，但对于队伍来说也是不错的助力。",
	["tid#GuideDes_153"]="先不要着急选择，闯王宝藏中有许多岔路，选择其中一条后，另一条路线就会坍塌，先去另一条岔路上看看情况再做选择吧。",
	["tid#GuideDes_154"]="据说击败这里的守卫可以获得奇物，奇物会为队伍提供强大的属性加成。不过可惜的是只能在宝藏中使用。",
	["tid#GuideDes_155"]="为了方便查看，不如我们把所有的奇物都放在一处吧。",
	["tid#GuideDes_156"]="少侠，四象阵开放了，一起去看一下吧。",
	["tid#GuideDes_157"]="这里就是四象阵了，这座塔中的每一层都关押着穷凶极恶的敌人。",
	["tid#GuideDes_158"]="据说这些敌人，都是连朝廷都无法处理的。所以只要击败这些敌人，就能够获得朝廷赐予的奖励。",
	["tid#GuideDes_159"]="这笔奖励对我们队伍的发展来说是不可或缺的，进去闯一闯吧。",
	["tid#GuideDes_160"]="少侠，帮会大厅修建好了，一起去看看吧。",
	["tid#GuideDes_161"]="这里就是帮会大厅了，在这里，可以选择一个帮会加入或是自己创建一个帮会。",
	["tid#GuideDes_162"]="江湖中，帮会就意味着朋友和靠山，是必不可少的。",
	["tid#GuideDes_163"]="少侠，论剑山庄开放了，一起去看看吧。",
	["tid#GuideDes_164"]="这里就是论剑山庄了，在这里你可以与其他少侠进行对战，赢取积分，获取更高的排名和奖励，去试试吧。",
	["tid#GuideDes_165"]="这里就是悬赏了，每天这里都会刷新一批任务，派遣侠客前往完成任务即可获取奖励。",
	["tid#GuideDes_166"]="需要注意的是，每个任务都有侠客品阶，阵营等需求，必须要满足需求才能够完成任务。",
	["tid#GuideDes_167"]="不多说了，快去试一试吧。",
	["tid#GuideDes_168"]="少侠，练武场修建好了，是时候选定一下长老了。",
	["tid#GuideDes_169"]="这里就是练武场了，在练武场里，当前拥有侠客中等级最高的五人会被选为长老。",
	["tid#GuideDes_170"]="选定长老后，可以选择其他侠客进行灌顶，被灌顶的侠客等级会被提升至五位长老中最低的等级。",
	["tid#GuideDes_171"]="大概就是这样。有了练武场之后，就能省下很多升级资源了。",
	["tid#GuideDes_172"]="好了，我带你进去看看吧。",
	["tid#GuideDes_173"]="少侠，悬赏任务开放了，快去看看吧。",
	["tid#GuideDes_174"]="即将开始新手教程，是否跳过？",
	["tid#GuideDes_175"]="如果觉得自身实力弱小，需要寻找一些保护和依靠的话，那么加入一个帮会是再好不过的选择。",
	["tid#GuideDes_176"]="当然，如果少侠觉得自身已经有了雄踞一方的实力，那么自己创建一个帮会也是不错的选择。",
	["tid#GuideDes_177"]="具体怎么做，少侠还是自己认真思考一下吧。",
	["tid#GuideDes_178"]="选择跳过后，之后所有的引导都将不会出现，确定吗？",
	["tid#GuideDes_179"]="是位厉害的敌人，大侠可要多加小心！",
	["tid#GuideDes_180"]="开启自动战斗后，侠客会自动释放绝技。",
	["tid#GuideDes_181"]="又一名新的侠客加入我们，不妨去看看吧。",
	["tid#GuideDes_182"]="新的侠客看来还需要提升一下才能帮助我们。",
	["tid#GuideDes_183"]="长按升级按钮，可快速提升侠客的等级。",
	["tid#GuideDes_184"]="太好了，又一位大侠加入了我们，回到战斗吧。",
	["tid#GuideDes_185"]="少侠请看，这就是守卫掉落的奇物。",
	["tid#GuideDes_186"]="每个守卫会掉落三个奇物，但少侠只能选择其中的一个。",
	["tid#GuideDes_187"]="至于如何挑选适合自己阵容和侠客的奇物，就需要少侠好好思考一下了。",
	["tid#GuideDes_188"]="这个奇物看起来很强力，就选它吧！",
	["tid#GuideDes_189"]="四象阵中，每层都有金木水火四种属性的怪物，击败这些怪物后，会获得对应属性的印记。",
	["tid#GuideDes_190"]="拥有印记时，与克制属性的怪物战斗，伤害会获得提升，与被克制属性的怪物战斗则会减少。",
	["tid#GuideDes_191"]="水克火，火克金，金克木，木克土，土克水。这些克制关系，少侠请牢记。",
	["tid#GuideDes_192"]="少侠当前获得的印记属性，会展示在这里。",
	["tid#GuideDes_193"]="当前印记的增益效果也会在这里显示。",
	["tid#GuideDes_194"]="点击任意空白位置关闭提示。",
	["tid#GuideDes_195"]="根据克制关系的话，接下来打这个怪物会简单一些，试试吧。",
	["tid#GuideDes_196"]="让我来会一会你！",
	["tid#GuideDes_197"]="神刀门下，向来正面应敌！",
	["tid#GuideDes_198"]="让这位大侠也加入战斗吧！",
	["tid#GuideDes_199"]="现在我们将物资赠与侠客，让他们变得更强吧。",
	["tid#GuideDes_1991"]="想必经过一番休整，侠客们会成为更加得力的助手~",
	["tid#GuideDes_1992"]="我们先来助侠客提升功力。",
	["tid#GuideDes_1993"]="选择合适的武器护甲，更能使侠客实力大增。",
	["tid#GuideDes_200"]="论剑山庄开启了，少侠不妨来看一看？",
	["tid#GuideDes_201"]="各大武林高手都在这里了，快进来吧！",
	["tid#GuideDes_202"]="琅嬛阁已经开放，少侠快随我来看看",
	["tid#GuideDes_203"]="点击琅嬛阁",
	["tid#GuideDes_204"]="请选择一本秘籍",
	["tid#GuideDes_205"]="装备这本秘籍",
	["tid#GuideDes_206"]="选择外功秘籍栏位",
	["tid#GuideDes_207"]="提升外功心法的等级",
	["tid#GuideDes_208"]="【【【【废弃】】】】",
	["tid#GuideDes_209"]="少侠，江湖中发布了不少悬赏任务，我们去看看~",
	["tid#GuideDes_210"]="就是这里了~",
	["tid#GuideDes_211"]="选择一个我们想做的吧。",
	["tid#GuideDes_212"]="让我看看……就委托这位大侠前去吧！",
	["tid#GuideDes_213"]="那么，一切便交给大侠啦！",
	["tid#GuideDes_214"]="任务已经完成，可以领取悬赏的奖励了~",
	["tid#GuideDes_215"]="少侠，侠客们可以通过打通经脉提升实力，要不要试试？",
	["tid#GuideDes_216"]="打开侠客的养成界面",
	["tid#GuideDes_217"]="打开经脉界面",
	["tid#GuideDes_218"]="激活经脉，提升侠客实力",
	["tid#GuideDes_219"]="为侠客装备一把神兵吧",
	["tid#GuideDes_220"]="打开侠客的养成界面",
	["tid#GuideDes_221"]="打开神兵列表",
	["tid#GuideDes_222"]="选择一把神兵装备上",
	["tid#GuideDes_223"]="为侠客们选择一种阵法吧",
	["tid#GuideDes_224"]="选择一个新的阵法",
	["tid#GuideDes_225"]="江湖论剑正在举办，少侠，我们也参加吧",
	["tid#GuideDes_226"]="打开江湖论剑",
	["tid#GuideDes_227"]="少主！山庄有人闹事，快随我来",
	["tid#GuideDes_228"]="点击少羽的头像与他对话接受任务",
	["tid#GuideDes_229"]="点击少羽的头像与他对话接受任务",
	["tid#GuideDes_230"]="与唐小夕对话获得任务的情报",
	["tid#GuideDes_231"]="回到飞云山庄去找线索",
	["tid#GuideDes_232"]="点击快捷栏去往后山探索",
	["tid#GuideDes_233"]="继续挑战，开始战斗吧！",
	["tid#GuideDes_234"]="我也是后排侠客，拖动我到后排位置",
	["tid#GuideDes_235"]="前面就是墨家的机关要塞天机楼，我们快去看看吧！",
	["tid#GuideDes_236"]="墨家没落后，有不少侠客前来探寻，今日我们也可一饱眼福了！",
	["tid#GuideDes_237"]="打败这些敌人，就可以得到墨家秘宝哦~",
	["tid#GuideDes_238"]="若我们的实力远强于敌人，就可以一路畅通无忧啦。",
	["tid#GuideDes_239"]="云游四方，功法不可荒废，要时时历练哦。",
	["tid#GuideDes_240"]="昔日墨者制机关兽玄武，置于此地，是为“玄武遗迹”。",
	["tid#GuideDes_241"]="游历多时，我们也来修整一下侠客的装备吧。",
	["tid#GuideDes_242"]="看看这位侠客可有何需要么？",
	["tid#GuideDes_243"]="这件装备可以强化！",
	["tid#GuideDes_244"]="我们来帮帮他吧！",
	["tid#GuideDes_245"]="这些都可以用作强化的材料~",
	["tid#GuideDes_246"]="好！现在便开始吧！",
	["tid#GuideDes_247"]="我们去强化一下侠客吧！",
	["tid#GuideDes_248"]="选择一个常用的侠客",
	["tid#GuideDes_249"]="这件装备可以强化！",
	["tid#GuideDes_250"]="尝试强化吧！",
	["tid#GuideDes_251"]="可以快速选择材料",
	["tid#GuideDes_252"]="好！强化开始！",
	["tid#GuideDes_253"]="我们游历江湖之时，都发生了什么呢？一起去看看吧~",
	["tid#GuideDes_254"]="我历经出海之事就发生在蓬莱小筑哦。",
	["tid#GuideDes_255"]="与这位小姑娘对话，听听看她会说些什么~",
	["tid#GuideDes_256"]="前往这里开始我们的江湖故事吧！",
	["tid#GuideDes_257"]="这里可以快速加入帮会",
	["tid#GuideDes_258"]="金属性的心愿单有空位！",
	["tid#GuideDes_259"]="点击未亮起的侠客就可将他加入心愿单！",
	["tid#GuideDes_260"]="从这里可以前往下一个地区！",
	["tid#GuideDes_261"]="闯王宝藏变幻莫测，内藏无数秘宝，我们可不能错过啊！",
	["tid#GuideDes_262"]="就是这里了~",
	["tid#GuideDes_263"]="好复杂的地形……先到前面看看吧。",
	["tid#GuideDes_264"]="走这里可以进入下一层",
	["tid#GuideDes_265"]="找个帮手吧！",
	["tid#GuideDes_266"]="在这里可以买到奇珍异宝！",
	["tid#GuideDes_267"]="若提升侠客的品阶，需要前往传功殿。",
	["tid#GuideDes_268"]="传功会提升侠客的最高等级和综合实力。",
	["tid#GuideDes_269"]="我们现在便去传功殿看看吧。",
	["tid#GuideDes_270"]="就从这位侠客开始吧。",
	["tid#GuideDes_271"]="练武场开启了，我们一起去看看如何？",
	["tid#GuideDes_272"]="行走江湖，武艺不可疏忽。让我们去练武场看看吧。",
	["tid#GuideDes_273"]="我们可以在这里练武过招，快速提升侠客的实力。",
	["tid#GuideDes_274"]="功力较高的大侠是授业侠客，在此修习，可到达他们的最低等级。",
	["tid#GuideDes_275"]="琅嬛阁已经可以使用了，在那里能够修习武功秘籍。",
	["tid#GuideDes_276"]="可以通过琅嬛阁中的秘籍来提升侠客的能力哦。",
	["tid#GuideDes_277"]="点击这里选择一位侠客吧~",
	["tid#GuideDes_278"]="选择一位开启经脉的侠客。",
	["tid#GuideDes_279"]="点击这里前往经脉页面。",
	["tid#GuideDes_280"]="要记得，消耗碎片也可以提升秘籍的星级",
	["tid#GuideDes_281"]="少侠，侠客可以通过改变阵法，获得不同的加成。",
	["tid#GuideDes_282"]="选择一个新的阵法吧，位处阵眼的侠客会更强喔。",
	["tid#GuideDes_283"]="使用心愿单可让想要的侠客出率相对提升",
	["tid#GuideDes_284"]="点击心仪的侠客，加入心愿单吧",
	["tid#GuideDes_285"]="我们获得了一张招募令，可以用它来招募侠客。",
	["tid#GuideDes_286"]="在客栈中使用招募令，就可以招募侠客了！",
	["tid#GuideDes_287"]="这里就是少侠的包裹啦。",
	["tid#GuideDes_288"]="先检查一下有没有遗漏吧~",
	["tid#GuideDes_289"]="既然收拾妥当，那就一起去海边出发吧~",
	["tid#GuideDes_290"]="就是这里了，少侠快跟上来~",
	["tid#GuideDes_291"]="点击这里可以确认详细信息。",
	["tid#GuideDes_292"]="探索闯王宝藏就可以发现各种奖励！",
	["tid#GuideDes_293"]="既然如此，我们就与他切磋一番~",
	["tid#GuideDes_294"]="好，让我们回去吧！",
	["tid#GuideDes_295"]="点击这里查看侠客的经脉。",
	["tid#GuideDes_296"]="选择侠客的经脉。",
	["tid#GuideDes_297"]="修习秘籍，可助大侠功力大涨。",
	["tid#GuideDes_298"]="还请大侠慎重选择，修习适合自己的秘籍为宜~",
	["tid#GuideDes_299"]="在琅嬛阁中可以将残本秘籍进行合订，选择可以合订的秘籍吧~",
	["tid#GuideDes_300"]="选好了可以合订的秘籍就可以合成啦~",
	["tid#GuideDes_301"]="少侠，有秘籍可以提升星级了。",
	["tid#GuideDes_302"]="点击升星按钮。",
	["tid#GuideDes_303"]="点击这里，返回挂机界面。",
	["tid#GuideDes_304"]="旅途劳顿，我这便带少侠前去放松一下吧！",
	["tid#GuideDes_305"]="江湖中有许多趣闻轶事，少侠可愿听一听？",
	["tid#GuideDes_306"]="那便来这里的茶馆吧~",
	["tid#GuideDes_307"]="你看，说书先生已经开始了，我们快进去吧！",
	["tid#GuideDes_308"]="在传记关卡中，每一关都会有强力助战侠客帮忙。",
	["tid#GuideDes_309"]="胜负乃兵家常事，少侠也不必太过在意。",
	["tid#GuideDes_310"]="少侠随我来，我们将平时练武的心得与游历的收获都寄放在这里。",
	["tid#GuideDes_311"]="让俺来助你！俺既抗揍还能砸晕敌人！",
	["tid#GuideDes_312"]="嘿嘿，就把俺放在前排吧！俺来保护其他的大侠！",
	["tid#GuideDes_313"]="高难度需要更多不同的侠客来完成，而且奖励也会更加丰厚呢。",
	["tid#GuideDes_314"]="一般情况下侠客们需要两到四个时辰才能完成悬赏。",
	["tid#GuideDes_315"]="不过这次的悬赏看起来很容易，只消片刻便能领赏了~",
	["tid#GuideDes_316"]="随着不断地向前游历我们就会遇到更高的悬赏。",
	["tid#GuideDes_317"]="悬赏人每天都会更新任务！",
	["tid#GuideDes_318"]="另外稀有的悬赏要先完成一些前置悬赏才会遇到呢。",
	["tid#GuideDes_319"]="少侠，是神秘的狐仙商人欸，他每次都会带着一批新商品出现呢！",
	["tid#GuideDes_320"]="之后我们就可以到商会再看他的商品，直到此次的迷宫关闭呢~",
	["tid#GuideDes_321"]="这是迷宫营地，可以在这里选择一名助战侠客结伴闯荡迷宫~",
	["tid#GuideDes_322"]="营地的侠客非常可靠，会一直陪伴我们直到我们这次迷宫结束呢！",
	["tid#GuideDes_323"]="比试之后，少侠的名次也会有所变化，加油哦！",
	["tid#GuideDes_324"]="排位越高每天和每周就能获得越多的元宝哦。",
	["tid#GuideDes_325"]="另外，论剑中也要记得守擂哦，可别忘了更新我们的防御侠客。",
	["tid#GuideDes_326"]="每天都可以来挑战玄武傀儡！",
	["tid#GuideDes_327"]="我们造成的伤害越多奖励越丰厚哦！",
	["tid#GuideDes_328"]="少侠，似乎我们到了传说中的四象阵，一起去看一下吧~",
	["tid#GuideDes_329"]="听说这里由鬼谷先生创建，有很多根据阵法摆放的侠客傀儡。",
	["tid#GuideDes_330"]="只要击败了这些傀儡就能获得鬼谷先生赠予的奖励哦！",
	["tid#GuideDes_331"]="这四象阵中，击败这些这些傀儡后就能获得对应的印记。",
	["tid#GuideDes_332"]="拥有印记，就能对克制属性印记的傀儡造成更高的伤害，反之则伤害变低哦。",
	["tid#GuideDes_333"]="属性间的克制关系少侠可要谨记呢。",
	["tid#GuideDes_334"]="少侠要不要加入一个帮会呀？",
	["tid#GuideDes_335"]="少侠可以通过帮会结识更多的朋友，还能增进自己侠客的武学哦。",
	["tid#GuideDes_336"]="我们可以通过铜币，修为，突破丹这三种东西来提升侠客们的能力。",
	["tid#GuideDes_337"]="不同的侠客发挥的作用也不尽相同，少侠可以适时选择提升对应的侠客呢~",
	["tid#GuideDes_338"]="少侠可知侠客们彼此之间是存在某种特定羁绊的哦。",
	["tid#GuideDes_339"]="当羁绊达成时侠客就会变得更强。",
	["tid#GuideDes_340"]="随着侠客们的功法日益精进，他们之间的羁绊也会更加牢固。",
	["tid#GuideDes_341"]="使得羁绊带来的提升愈发强大哦~",
	["tid#GuideDes_342"]="少侠，我们现在拥有好多元宝了，我们不如去聚义客栈招募更多同行的侠客吧~",
	["tid#GuideDes_343"]="少侠，这里的传说结束了，你可以继续探索，也可以回到江湖大地图。",
	["tid#GuideDes_344"]="若有意气相投的侠客，少侠可于此结下不解之缘。",
	["tid#GuideDes_345"]="那么谁是你最心仪的侠客呢？快做出选择吧~",
	["tid#GuideDes_346"]="少侠是否想和侠客们结下更深的情谊呢？",
	["tid#GuideDes_347"]="前缘桥已经开启，少侠请随我来~",
	["tid#GuideDes_348"]="听闻世间异宝，皆汇聚于聚宝山，我们也去看看吧！",
	["tid#GuideDes_349"]="就是这里了~",
	["tid#GuideDes_350"]="原来如此~看来能有何收获，还要看少侠的运气了~",
	["tid#GuideDes_351"]="在此用心经营一番，想必会大有所获~",
	["tid#GuideDes_352"]="那便劳烦大侠啦！",
	["tid#GuideDes_353"]="实力越强的侠客，能获得的收益越多哦~",
	["tid#GuideDes_354"]="便让最强的侠客上阵吧！",
	["tid#GuideDes_355"]="少侠，新的论剑大赛开始了！",
	["tid#GuideDes_356"]="来这里展示你真正的实力吧！",
	["tid#GuideDes_357"]="",
	["tid#GuideDes_358"]="",
	["tid#GuideDes_359"]="听说武道场可以赢取很多补给，我们也去看看吧！",
	["tid#GuideDes_360"]="都说此处奖赏丰厚，真让人跃跃欲试呢！",
	["tid#GuideDes_361"]="少侠，快开始吧！",
	["tid#GuideDes_362"]="少侠已越来越强了，也当见识一下新的考验了！",
	["tid#GuideDes_363"]="去试炼遗迹看看！",
	["tid#GuideDes_364"]="这里每日都有强大的侠客现身，与其切磋，可获益无穷~",
	["tid#GuideDes_365"]="快试试自己的身手吧！",
	["tid#GuideDes_366"]="若对地形不熟，可用这张地图辨清道路。",
	["tid#GuideDes_367"]="刚刚丫鬟来报，岛主有东西留给我们，先回去看看吧。",
	["tid#GuideDes_368"]="应该就是它了~",
	["tid#GuideDes_369"]="快去一探究竟吧！",
	["tid#GuideDes_370"]="我们现在便试试吧！",
	["tid#GuideDes_371"]="少侠的武功又精进了呢，我们再去论剑山庄比试一番吧~",
	["tid#GuideDes_372"]="少侠快来！",
	["tid#GuideDes_373"]="每位侠客各有所长，少侠可要用心排兵布阵哦~",
	["tid#GuideDes_374"]="快去试试吧！",
	["tid#GuideDes_375"]="听闻天机楼有所异动，似乎与以往不同了呢~",
	["tid#GuideDes_376"]="少侠，我们去看看吧！",
	["tid#GuideDes_377"]="原来是四座望楼已经开启~其中似有四象五行之意，快领略一番吧~",
	["tid#GuideDes_378"]="传闻苗疆神秘莫测，少侠想不想探寻一番~",
	["tid#GuideDes_379"]="也许会有意想不到的收获呢！",
	["tid#GuideDes_380"]="到这边来！",
	["tid#GuideDes_381"]="此处可寻得中原遗落的宝物，少侠可将它们带回。",
	["tid#GuideDes_382"]="只要战胜这些对手就好了！",
	["tid#GuideDes_383"]="少侠出手，果然不同凡响！我们先回去吧~",
	["tid#GuideDes_384"]="这里以后就是我们的驻扎地啦！记得回来看看哦~",
	["tid#GuideDes_385"]="排兵布阵之道，就看少侠的了~",
	["tid#GuideDes_386"]="与之一战，可得取墨家宝物哦。",
	["tid#GuideDes_387"]="少侠，我们去试试吧！",
	["tid#GuideDes_388"]="这些贼人太可恶了，一定要打败他们！",
	["tid#GuideDes_389"]="此战不可强攻，先撤离吧。",
	["tid#GuideDes_390"]="少侠，看你的了！",
	["tid#GuideDes_391"]="以真气冲击经脉，可使功力大涨。",
	["tid#GuideDes_392"]="平日多游历，或挑战四象阵，都可积攒真气。少侠快试试吧~",
