	["tid#MazeMapName_1"]="迷宫层的名字",
	["tid#MazeMapName_2"]="迷宫层的名字",
	["tid#MazeMapName_3"]="迷宫层的名字",
	["tid#MazeMapName_32"]="迷宫层的名字",
	["tid#MazeCellTypeName_1"]="卸岭力士",
	["tid#MazeCellTypeName_2"]="摸金校尉",
	["tid#MazeCellTypeName_3"]="发丘天官",
	["tid#MazeCellTypeName_4"]="援兵守卫",
	["tid#MazeCellTypeName_5"]="药泉",
	["tid#MazeCellTypeName_6"]="济世罗汉",
	["tid#MazeCellTypeName_7"]="狐仙商人",
	["tid#MazeCellTypeName_10"]="陵墓守卫",
	["tid#MazeCellTypeName_11"]="探灵先驱",
	["tid#MazeCellTypeName_12"]="宝箱",
	["tid#MazeCellTypeName_13"]="出口",
	["tid#MazeCellTypeDes_1"]="来宝藏中寻宝的江湖杂鱼并不专业，看起来不太厉害的样子。",
	["tid#MazeCellTypeDes_2"]="来宝藏中寻宝的武林高手，看起来有点东西。",
	["tid#MazeCellTypeDes_3"]="古墓请来镇守墓穴的绝世高手，非常危险。",
	["tid#MazeCellTypeDes_4"]="武林同盟派来的援救的侠客，可以选择一位雇佣参与后面的冒险",
	["tid#MazeCellTypeDes_5"]="天然生成的药泉，当前受伤的侠客在此饮用泉水可恢复全部生命",
	["tid#MazeCellTypeDes_6"]="济世罗汉神像，在这里出现有些诡异，但是还是起作用的，祭拜会让一位已经重伤的侠客痊愈",
	["tid#MazeCellTypeDes_7"]="来历不明的神秘商人，遇到后会在闯王商店中添加新的商品",
	["tid#MazeCellTypeDes_10"]="被古墓改造过尸化之后的侠客，能力强大到变态，帮他解脱他将追随你",
	["tid#MazeCellTypeDes_11"]="死在这里的先驱，临死都要守护他得到的宝藏，击败他获得以下奖励之一",
	["tid#MazeCellTypeDes_12"]="占位符",
	["tid#MazeCellTypeDes_13"]="装满",
	["tid#MazeCellTypeDes_14"]="",
	["tid#MazeTipsDes_1"]="当前迷宫已通关，是否消耗1次挑战次数扫荡该迷宫？扫荡后可直接获得奖励。",
	["tid#MazeTipsDes_2"]="特权等级8级后开启迷宫扫荡功能",
	["tid#boat_reset1"]="重塑侠客会回到初始等级并返还全部培养资源",
	["tid#boat_reset2"]="1.重塑侠客，回收消耗的资源。\\n\\n2.重塑完成后，侠客重塑为初始等级，同时已装备物品、培养消耗的所有资源都将返回至背包中。",
	["tid#boat_reset3"]="描述随便来点",
	["tid#boat_rolereset"]="侠客返璞回到初始职业等级并返还全部培养资源",
	["tid#boat_sell1"]="可以遣散普通品质的侠客获得相忘币和全部培养资源",
	["tid#boat_sell2"]="1.可以遣散普通品质侠客，大侠品质侠客无法遣散，但是可以在大圣堂进行强化。\\n\\n2.遣散完成后，将失去对应侠客，但是已装备的物品、培养消耗的所有资源豆浆返回至背包中。",
	["tid#boat_sell3"]="描述随便来点",
	["tid#wish1"]="心愿侠客",
	["tid#wish2"]="1.可以选择3位心愿侠客。\\n\\n2.通过招募获得紫品侠客时，会有更高几率是心愿侠客，但是并不影响获得紫品侠客的概率。\\n\\n3.每一阵营的侠客只能选择一位。\\n\\n4.成功招募心愿侠客后，对应心愿侠客状态变为【已实现】，已实现的心愿侠客无法获得心愿单的出现概率加成，此时建议替换为其他侠客。心愿实现状态每周一重置。",
	["tid#wish3"]="下周一可以再次许愿该侠客",
	["tid#wish4"]="距离心愿实现重置还有%s",
	["tid#luky1"]="祝福侠客",
	["tid#luky2"]="1.可以选择1位侠客成为祝福侠客。\\n\\n2.每进行1次侠客招募，可以累积1点祝福值，祝福值集满时，可以领取祝福侠客。\\n\\n3.每领取一次祝福奖励，都将提升再次触发祝福奖励需要的祝福值，每月1日重置。\\n\\n4.友情招募无法累积祝福值。\\n\\n5.祝福值有累积上限，达到上限后将无法继续获得祝福值。\\n\\n6.重置时只会将触发祝福所需要的祝福值回归至初始状态，已经获取的祝福值不会被重置。",
	["tid#luky3"]="本月祝福次数已用完",
	["tid#mercenary1"]="门客",
	["tid#mercenary2"]="1.少侠可向好友或帮会护法发起雇佣请求，对方同意之后，可以使用雇佣的门客上阵；\\n\\n2.少侠的同一个侠客只能借给一名好友，可借用一周，雇佣的门客在下周一0时统一归还；\\n\\n3.少侠每周最多只能向好友雇佣3个金色品级以上的侠客；\\n\\n4.雇佣到的侠客战力会由好友与自己的战力决定；\\n\\n5.在四象阵、天机楼、主线关卡中每周只能使用一次门客，在闯王宝藏中可以反复使用；\\n\\n6.只有战斗胜利才会扣除使用次数；\\n\\n7.不能雇佣超过7天未上线的好友的侠客。",
	["tid#friend1"]="好友",
	["tid#friend2"]="1.最多可以添加30位好友。\\n\\n2.可以与好友的阵容进行切磋验证彼此实力！\\n\\n3.每天可赠送30个好友“侠缘”，领取20个好友赠送的侠缘。\\n\\n4.获得的侠缘可以用来抽取侠客。",
	["tid#ranking1"]="风云榜",
	["tid#ranking2"]="1.每个风云榜都有奖励任务，并显示本服排名最高少侠的进度。\\n\\n2.本服出现完成任务的少侠时，所有少侠都能获得任务奖励。\\n\\n3.本服首位达成任务的少侠信息将显示在界面中，前五名达成的少侠则显示在日志内。\\n\\n4.阵营积分榜的分数由少侠拥有的侠客及其品质决定：\n其中紫品90分，紫品1星180分；\n橙品360分，橙品1星650分，橙品2星900分；\n红品1260分，红品1星1620分，红品2星1980分，红品3星2340分；\n白品2700分，白品1星3060分，白品2星3420分，白品3星3780分，白品4星4140分\n彩品4500分，彩品1星4860分，彩品2星5220分，彩品3星5580分，彩品4星5940分，彩品5星6300分\n",
	["tid#tower1"]="四象阵",
	["tid#tower2"]="1.每天可获得1次挑战次数；\\n\\n2.挑战次数可以累积，但最多累计5次；\\n\\n3.消耗一次挑战次数可以激活四象阵；\\n\\n4.四象阵中的每个敌人都会携带一个奇物且会获得其属性加成，击败敌人可以夺取奇物；\\n\\n5.击败全部四个敌人后会出现四象首领，首领没有奇物加成，但拥有极强的战力；\\n\\n6.击败首领后，即为通关了四象阵并会获得奖励；\\n\\n7.轮换奖励的数量和类型会每天更换；\\n\\n8.到达指定vip等级后，可以消耗元宝，获得额外的扫荡次数；\\n\\n9.四象阵内的敌人战力会随着玩家推关进度提升，且每次激活四象阵，里面的敌人都会重新随机生成；",
	["tid#moon_shadow_test01"]="侠影试炼",
	["tid#moon_shadow_test02"]="1.侠影试炼中的每个敌人都会携带一个遗物且会获得其属性加成，击败敌人可以夺取奇物；\\n\\n2.击败全部四个敌人后会出现四象首领，首领没有奇物加成，但拥有极强的战力，且不可击杀；\\n\\n3.首领战结束后，根据首领战伤害进行排行，伤害最高者会获得的丰厚奖励；\\n\\n4.遗物每日刷新；\\n\\n5.自试炼第二日起，玩家获取的金山派品质达到紫1星以上，挑战中所有友方侠客攻击力增加10%",
	["tid#moon_shadow_story01"]="自小生活在西山的求伯君，很早便展现出惊人的武学天赋，开明的父亲为了求伯君能够发扬自己的天赋，便托乡里有本事的人将求伯君送入了名门金山派继续研习武学。而求伯君也不负众望，在金山派中一鸣惊人，以其惊人的天赋与刻苦修炼的品质，被老掌门赏识，不出几年便成为了金山派的首席大弟子。",
	["tid#moon_shadow_story02"]="一切都很顺利，求伯君从老掌门处顺利继承金山派掌门之位，并开始带着金山派在武林中崭露头角。勤奋的求伯君改良金山派原有的武学，独创出更厉害的内功心法，一时轰动整个江湖。然而，一时风头无两的金山派与求伯君的成就很快也遭到了不怀好意的人的觊觎。江湖中的人人闻之色变的巨门天忍教，想与金山派结盟，声称要共同维护江湖的安宁，彼时年轻的求伯君轻信了天忍凌峰楼楼主凌雪寒的话，答应了结盟的事情。",
	["tid#moon_shadow_story03"]="为人正直的求伯君没有想到，天忍教的结盟只是障眼法，这个江湖之中，还有他意想不到的人心险恶。潜伏于金山派多年后，天忍教开始显露出野心。他们模仿着金山武学的精髓，“创造”了几乎一模一样的“凌绝剑式”，对外却说是自己的独门绝学，于江湖之中大肆宣扬。金山派一向行事低调，渐渐地，世人只知凌绝剑式威力无双，而金山弟子行走江湖，却反会被当作模仿者。本应独享盛名的金山派，却因此而遭遇了空前的危机。",
	["tid#moon_shadow_story04"]="面对来自整个江湖的压力，求伯君没有退缩，他开始闭关修炼，带着十几个同门一起，苦心钻研，寻找金山派的出路。虽然世间有诸多纷扰，但他坚信，实力才是证明自己的最好方式。一年后，天忍教接到了来自金山的战书，在江湖中传得沸沸扬扬。那一战，求伯君在整个江湖的瞩目下，以金山的剑法，击败了天忍的凌绝剑式。他将天忍教假意结盟，却背后暗算的阴谋公之于众，赢回了金山的清正之誉。无数次夜以继日的艰辛，终于在这一刻得到了证明。",
	["tid#moon_shadow_story05"]="阴谋被揭穿后，天忍教仍不死心。一计不成，他们便想到了以数量取胜、“壮大”门派声势的对策。他们暗中制作金山剑谱的手抄本，以天忍教的名义，招揽寒门之子，将他们纳入自己门下。这些门徒或因心术不正、或因走投无路，纷纷被蛊惑而来，天忍教再次与江湖之中声名渐起，成了金山派不容小觑的威胁。他们甚至打着“和平共处”的旗号，想要招揽求伯君为他们效命，但此时求伯君已看清了他们的嘴脸，毅然拒绝了他们。",
	["tid#moon_shadow_story06"]="随着这场闹剧愈演愈烈，求伯君意识到，自己肩负的，已不只是金山派的名誉，更是整个江湖的公道。几年来和天忍教交手各有胜负，而天忍教又擅长混淆视听，如此以往，这种黑白不分的局势，不知会毁去多少后生的前途。为了得到更强的力量，彻底击碎天忍教的阴谋，求伯君当机立断，只身出海去往武学的至臻之地——蓬莱。",
	["tid#moon_shadow_story07"]="蓬山归来的求伯君，一举荡平了天忍教所有的阴谋，此盛举被江湖人称“君之传奇”。随后不久，求伯君便决定退隐江湖，将掌门之位传于可靠的金山后辈。至于求伯君隐退的原因，江湖上也是众说纷纭，有人说求伯君经年勤勉于武学身体总有些损伤，与天忍一决之后，身体状况便大不如前，隐退也是无奈之举；然而也有人说，求伯君在蓬莱之间有所开悟，如今心境平和，自己的使命也已经完成，更想如闲云野鹤浪荡于江湖之中。不过究竟为何，世人也只是纷纭猜测，唯独留下的江湖传奇，永远传颂于武林之间。",
	["tid#moon_shadow_other01"]="荡尽重魔",
	["tid#moon_shadow_other02"]="攻击力提升{1_value}",
	["tid#dragonsword_story01"]="春秋战国，有铸剑人欧冶子擅冶金，于越国开山取铁，取出的铁砂，收集淘洗，可以练出草钢，进一步锻造捶打，手工磨制，便可以打造宝剑。\n欧冶子遂与著名剑师干将一同，铸剑三枚，其一「龙渊」。\n龙渊剑是古代名剑，代表着诚信高洁，刚正不阿。是历史上第一把铁剑，铁剑与青铜剑不同，锋利无比、寒气逼人，开创了中国冷兵器的铸造先河。",
	["tid#dragonsword_story02"]="春秋时期，春秋吴国大军事家伍子胥一家为奸臣所害，父母以及兄长被杀，伍子胥逃亡。伍子胥出了昭关，一路疾驰至长江之滨，见江水滔滔，暗自焦心，身后追兵将至，如何是好？\n正巧此时遇到一个渔翁，愿意渡他过河，帮他掩盖岸上的追击，伍子胥心存感激。\n伍子胥逃脱追兵后，问渔翁姓名，答曰“鱼丈人”。伍子胥掏出佩戴的宝剑，打算赠与渔翁，以答谢救命之恩。\n渔翁接过宝剑，伍子胥临行嘱咐渔翁说，后面有追兵过来千万不要泄露我的行踪。\n渔翁见状，拔剑自刎，以死明志，用自刎保留了自己高尚的品格。",
	["tid#dragonsword_story03"]="古说东华山后山有奇妙仙境，更有老龙泉一眼，汉高祖刘邦少年时期常在此玩耍，每每来到龙泉，都能看到一位白发老人在这里收集铁砂炼钢打铁。久而久之少年刘邦与老翁攀谈。\n刘邦问为何很久以来老人都在叮叮当当的打同一块铁。老人说铁如果不经过千锤百炼是很难形成宝剑的。老人还说要锤炼七七四十九天，炼成世上最好的宝剑之后就送给皇上。\n少年刘邦志气高远，直言道当时的皇上暴虐无度，送给皇上还不如送给自己。\n老人认为刘邦是未来的真龙天子，就承诺打好了宝剑送给他，取名为龙泉宝剑。\n后来，刘邦在芒砀山斩蛇起义，就是用的这把龙渊宝剑。",
	["tid#dragonsword_story04"]="雷焕，字孔章，生卒年不可详考，今江西省丰城市秀市镇雷坊村人。东晋名士，曾为丰城县令。\n雷焕当年成为丰城县令后，为了建造监狱，挖地40余尺，挖到一个青金石做的大箱子。箱子里有两把剑，还有一封干将、莫邪写的书信，从信上看来，这两把剑应该出自于干将之手，经过推断，得知一把叫做龙渊剑，一把叫做太阿剑。\n雷焕挖到龙渊剑的时候，发现上面布满了锈迹，后来咨询了当时的铸剑大师好友，得知可以用华山的黄土两升来打磨。",
	["tid#dragonsword_story05"]="雷焕挖到龙渊剑时，上面锈迹斑斑，于是雷焕找到了自己的好友，著名剑师张华，向他取经。\n张华拿到宝剑，欣赏了一番，大赞其铸造工艺。雷焕问这锈迹是否有方法去除，使得宝剑再现光辉。张华指出可以取华山北部的黄土岩来研磨。\n雷焕命人取来黄土岩，张华亲手研磨，果然经过研磨和擦拭，宝剑光焰照耀，所见之人无不惊愕万分。雷焕将龙渊剑赠与张华，以表感谢。\n后张华偶然获得华阴赤土，用赤土磨拭，剑的光华愈加精明，剑的光华甚至可以拥有杀伤力。",
	["tid#dragonsword_story06"]="唐代龙泉地区产的剑，但凡是名剑，均称之为龙泉剑。但是真正锋利无比削铁如泥的宝剑“龙渊”，其实在唐代皇帝李渊身边，只不过李渊因名字带有“渊”字，故将“龙渊剑”改名为“龙泉剑”，曰“七星龙泉”。\n李渊非常珍视这把宝剑，常常带在身旁，用来提醒自己要为人诚信、做事高洁。李渊死后，将这把剑传给了李世民，希望把强兵强国和刚正不阿的箴言留给后代皇帝。李世民死后，“七星龙渊”与李世民一起葬在了昭王陵。",
	["tid#dragonsword_story07"]="欧冶子制剑之业在龙泉递代相袭，在安徽巢湖及浙江永嘉等地亦发掘到清代的龙泉剑。\n龙渊剑长约77~82厘米，宽约2.6~3.5厘米，重达1kg左右。铸造之时历经“集铁砂”、“炼钢”“锻造”“手工打磨”全部流程，是我国铸剑工艺新时代的开端。\n1956年，浙江龙泉组织宝剑艺人，先后成立宝剑生产小组、宝剑生产合作社和龙泉宝剑厂。龙泉宝剑曾被选为国礼赠送给外国元首和友人。\n如今龙泉铸剑企业已近百家，成了名副其实的剑都。龙泉宝剑自铸剑鼻祖欧冶子创制至今，已曲曲折折地经历了二千五百多年的漫长岁月，到了今天，才有了更为灿烂光明的前景。",
	["tid#evil_shadow_story01"]="魅影试炼",
	["tid#evil_shadow_story02"]="她出生在一个机关师的家庭中，父亲父亲是一名优秀的机关师，他一直很爱自己这个女儿。吕珂虽然长相平凡，但是聪明过人，很小的时候就能掌握很复杂的算数与术数，而且动手能力也极强，但没有堕下山崖之前，她已经可以像父亲一样做出复杂的机械，擅长将各种各样的算式熟练解出。",
	["tid#evil_shadow_story03"]="她少女时期结识了好朋友小琴，小琴面容姣好，但是愿意和平凡的她一起玩耍，这让她十分感动，直到父亲把自己许配给镇上的一个帅气青年，小琴变得不太对劲，在一次两人出去游玩，小琴把她推下山崖，她摔断了脊椎，永远无法站立，小琴却嫁给了帅气青年人。",
	["tid#evil_shadow_story04"]="父亲不忍心让女儿卧床不起，于是就穷尽毕生之力，也在她的天才思路协作之下，为女儿打造了一辆非常精密的轮椅，这台轮椅的动力，驱动，无人可知父亲对此付出的心血，她自己是知道的，可是在心里深处，她又无法原谅小琴，于是她开始憎恨年轻貌美的姑娘，也憎恨只看容貌的无知青年小伙子。",
	["tid#evil_shadow_story05"]="现在，她可以驱动轮椅，很轻松地翻越矮小的山丘，甚至通过自己的改进，轮椅也可以载着她渡过河流，渐渐地，她在轮椅上增加了很多能够摄人心魄的内容，这样常年的生活，使她的内心变得阴暗孤僻，直到有一天，邪极坊的人找上门来，她得知自己的父亲是邪极坊的机关师，她知道，自己的价值终于要得到重视了。",
	["tid#evil_shadow_story06"]="邪极坊的人做梦也想不到，他们带回了怎样的一个仿佛从无间地狱带来的可怕恶鬼。吕珂在几年之间逐渐依靠着从父亲那里学来的机关术，制造了大量的傀儡。然后在某一天夜里，邪极坊的其他人全部消失了，几年之后他们似乎又回来了，作为傀儡，吕珂的傀儡。",
	["tid#evil_shadow_story07"]="昔日的经历郁结于心，让吕珂有了极强的控制欲。她越来越觉得，人心都是污浊、险恶的，需要自己去“矫正”一番。而傀儡虽不像常人一样心存恶念，却也无法如她所想，完全受她操控。直到有一天，邪极坊来了一个名叫魏途殊的少年。借助魏途殊的意念之力，吕珂得以操纵更多的傀儡，使它们按她的意愿行动。几年之内，邪极坊也逐渐壮大，吕珂有了越来越多的“属下”。",
	["tid#evil_shadow_story08"]="邪极坊逐渐变成令吕珂满意的“净土”，但她并不满足于此。随着魏途殊功力的增长，吕珂的野心也越来越大，她想要建立一个再没有虚伪与邪恶的、“纯善”的世界。凡人见识浅薄，她就借助意念之力，将自己的心智“赐予”他们；那些心术不正、难以拯救的，就助他们“重生”。中原之地，在吕珂眼里已过于污浊，她要寻找一方世外净土，来容纳自己的“至善”天下。于是有一天，她和魏途殊一道去了蓬莱。",
	["tid#evil_shadow_test01"]="魅影试炼",
	["tid#evil_shadow_test02"]="1、活动期间玩家挑战魅影试炼可以获得伤害排行奖励。\n2、活动期间伤害排行榜每日刷新。\n3、榜单奖励通过邮件发放。",
	["tid#crystal1"]="练武场",
	["tid#crystal2"]="1.等级最高的5个侠客将自动成为授业长老。\\n\\n2.放入修行侠客栏位的侠客,将会提升至长老中的最低等级。但是非大侠侠客只能提升到120级。\\n\\n3.在修行栏位的侠客无法进行升级，只有离开栏位后才可以升级。\\n\\n4.卸下侠客的栏位会有冷却时间，冷却完毕后可以再次放入侠客。冷却时间可以使用元宝来清除。非卸下操作导致的栏位清空（进阶消耗等）不会带来冷却时间。\\n\\n5.5名长老等级都达到300级后，可以解锁更高等级上限。\\n\\n6.解锁等级上限后，练武场等级可以从300级直接提升。所有长老默认放入新开放的祈愿栏位中（如此时将侠客卸下则为1级）。少侠可以消费资源直接升级练武场从而获得祈愿侠客的更高等级。",
	["tid#token_money_test1"]="返利说明：\n1、累计充值5000元以下（包含5000元），正式上线后可以领取100%的代金券以及等值的元宝，共计200%的返利奖励。\n如：曙光测试期间充值30元2笔、98元1笔，正式上线时可领取30元代金券x2、98元代金券x1、元宝x1580\n2、充值5000元以上，正式上线后可以领取100%的代金券以及50000元宝。\n如：曙光测试期间充值648元10笔，共计6480元，正式上线时可领取648元代金券x10、元宝x50000\n注意事项：\n1、正式上线后使用相同的账号登录才可以领取封测返利奖励\n2、正式上线后符合条件的少侠可以在主界面上领取封测返利奖励\n3、返利奖励可以在任意服务器内领取，但仅限领取一次\n4、正式上线时不继承曙光测试中的月卡、超级月卡、封测基金等进度\n5、领取方式可能有变更，请以正式上线时为准。",
	["tid#token_money_test2"]="参与测试且付费的少侠，可在本界面领取返利。",
	["tid#cathedral102001"]="传功殿",
	["tid#cathedral102002"]="1.在传功殿内，可以消耗材料提升侠客品质；\\n\\n2.传功材料为一定数量符合条件的侠客；\\n\\n3.传功后，被消耗的侠客会消失，同时穿戴在材料侠客身上的装备、培养消耗的铜钱、经验和突破丹会返回到行囊中。\\n\\n4.非【大侠】侠客无法提升到红品和以上品质",
	["tid#hero_return1"]="可以将橙色及以上品质的侠客最多回退至紫+品质并返还所有资源材料。",
	["tid#hero_return2"]="1.可以将橙品及以上品质的侠客回退至紫+品质，\\n\\n2.回退时会返还进阶时消耗的所有侠客和培养该侠客消耗的所有资源。\\n\\n3.只能对通过进阶操作获得的侠客进行操作，直接获取的侠客和通过回退获得的侠客都无法进一步回退。",
	["tid#mustdo1"]="抵制不良游戏，拒绝盗版游戏。注意自我保护，谨防受骗上当。\\n适度游戏益脑，沉迷游戏伤身。合理安排时间，享受健康生活。",
	["tid#stage_battle90001"]="世界首领甲",
	["tid#stage_battle90002"]="世界首领乙",
	["tid#boss_rush1"]="1.每天都有机会挑战玄武遗迹，在0时重置挑战次数；\\n\\n2.对机关玄武造成的伤害越高，即可获得更多奖励。；\\n\\n3.可以使用扫荡直接消耗次数获得奖励，无需反复挑战。\\n\\n4.击杀玄武机关后会登上玄武英雄录，榜单根据击杀时间排名每天刷新排行榜，本服前5人击杀后即可领取其对应奖励。",
	["tid#boss_rush2"]="1.根据每个少侠的最高伤害，排名前100的少侠将进入王者等级（只显示前50名）；\\n\\n2.其他各档内还分为若干小段，不同段位奖励不同；\\n\\n3.排行榜可以查看其他少侠的战斗回放，作为阵容和手法参考；\\n\\n4.排行榜的情况会随时变化，最终奖励以结算时的数据为准",
	["tid#boss_rush3"]="玄武遗迹",
	["tid#boss_rush4"]="远古剑魂",
	["tid#boss_rush5"]="1.每日有三次机会参加帮会秘境；\\n\\n2.每次根据伤害发放道具奖励，伤害越高奖励越多\\n\\n3.每次挑战结束都会有一个随机奇物进入帮会奇物库，第二天少侠可以选择适合的奇物挑战BOSS获得更多奖励；",
	["tid#notice_bag1"]="部分物品已经达到持有上限，请整理背包。",
	["tid#notice_bag2"]="侠客数量已经达到持有上限，请前往传功殿进阶。",
	["tid#maze_text1"]="1.闯王宝藏前4轮为新手期，期间每天都会重置并返还一次挑战次数；\\n\\n2.从第5轮开始，新手期结束，闯王宝藏将变为每48小时重置一次，并返还一次挑战次数；\\n\\n3.每次进入迷宫时，里面的怪物、宝箱、事件都将会重新随机生成；\\n\\n4.达到指定推图关卡并通关前置迷宫后可以解锁新的迷宫，部分迷宫需要达到指定的赛季才能解锁；\\n\\n5.每次闯关时，少侠只能从多个难度的迷宫中选择一个进入，在选择的迷宫中不断向下探索并击败敌人即可通关；\\n\\n6.迷宫重置时，若少侠仍未通关迷宫，则会强制结算奖励并重置迷宫；\\n\\n7.在迷宫中探索、开启宝箱可获得宝藏币，宝藏币可以在闯王商店中兑换货物；\\n\\n8.挑战次数可以累积，最多可以累积3次；",
	["tid#maze_text2"]="闯王宝藏",
	["tid#maze_text3"]="1.闯王宝藏前4轮为新手期，期间每天都会重置并返还一次挑战次数；\n2.从第5轮开始，新手期结束，闯王宝藏将变为每48小时重置一次，并返还一次挑战次数；\n3.每次进入迷宫时，里面的怪物、宝箱、事件都将会重新随机生成；\n4.达到指定推图关卡并通关前置迷宫后可以解锁新的迷宫，部分迷宫需要达到指定的赛季才能解锁；\n5.每次闯关时，少侠只能从多个难度的迷宫中选择一个进入，在选择的迷宫中不断向下探索并击败敌人即可通关；\n6.迷宫重置时，若少侠仍未通关迷宫，则会强制结算奖励并重置迷宫；\n7.在迷宫中探索、开启宝箱可获得宝藏币，宝藏币可以在闯王商店中兑换货物；\n8.挑战次数可以累积，最多可以累积3次；",
	["tid#notice_bag3"]="侠客数量已经达到持有上限，剩余侠客已通关邮件发放。",
	["tid#fangchenmi21"]="现在暂时不能登录游戏，根据健康系统规则，每日22:00-次日8:00无法登录游戏，请合理安排游戏时间。",
	["tid#fangchenmi22"]="累计在线时间已满1.5小时，请下线休息，做适当身体活动。",
	["tid#fangchenmi23"]="累计在线时间已满3小时，请下线休息，做适当身体活动。",
	["tid#fangchenmi24"]="根据相关法规，15日之内游客仅可游玩1小时，当前游客账号已达到游玩时间上限。",
	["tid#legend1"]="1.每天零点时，江湖传奇中会生成一场战役，供少侠进行挑战；\n2.根据每个少侠挑战的成绩，会在当前服务器中生成排行榜，并在每天晚上24点重置时，根据排名发放邮件奖励；\n3.少侠可以重复挑战当天的战役，以追求更高的排名；\n4.当玩家的挑战成绩达到需求后，战役难度会升级，战役中的敌人等级和属性都会得到提升；\n5.在排行榜中进行排名时，会优先按照战役的难度从高到低进行排名，当战役难度相同时，才会按照战役的成绩进行排名；\n6.具体玩法规则可以在战役的玩法说明中查看；\n7.无双模式难度升级条件：在对应难度下击杀一定数量的敌人",
