	["tid#arena_explain1"]="争锋论剑",
	["tid#arena_explain2"]="1.争锋论剑每两周为一轮，每轮结束时根据结算时的排名发放奖励，并重置积分；\\n\\n2.每轮开启后必须进入一次擂台才能获得初期积分并获得排名，初期积分会根据上轮成绩而有不同\\n\\n3.论剑后，胜者积分提高，败者积分下降\\n\\n5.每天有免费挑战的机会，次数用尽后可以消耗论剑书进行挑战\\n\\n6.每天晚上24时根据当时排名发放每日奖励。",
	["tid#arena_explain3"]="天下演武",
	["tid#arena_explain4"]="1.天下演武每周为一轮，采用段位制，根据少侠排名分为江湖新秀到武林至尊7个段位；\\n\\n2.随着段位提高获得演武币的效率增加，进入武林至尊段位后可获得演武积分；\\n\\n3.每轮结束后演武积分前128名的少侠获得巅峰论剑的参赛资格，满足巅峰论剑侠客要求的选手可参加（具体见巅峰论剑说明）；\\n\\n4.赛季结束后演武积分将被清空；\\n\\n5.挂机获得的演武币将存放在天下演武奖励箱中，奖励箱有获取上限，当上限满时则不会继续累积，请少侠及时手动领取奖励；\\n\\n6.演武币宝箱中最多累计50000演武币，达到上限后无法继续累计，请及时领取；\\n\\n7.天下演武局内战斗采用3局2胜制，少侠可以在防御按钮中调整自己的防御阵容；\\n\\n8.进攻的少侠必须有三个以上队伍，每个队伍中至少需要1个侠客，先获得两局胜利者胜出；\\n\\n9.单局获胜条件有两个，满足其一即获胜，条件一：全灭对方侠客获得一场胜利，条件二：战斗时长为1分30秒，战斗超时防守方获胜；\\n\\n10.每轮内未登录的少侠将无法获得巅峰论剑资格。",
	["tid#arena_explain5"]="积分排行榜",
	["tid#arena_explain6"]="每轮结束后累计排名前十的且至少有5分传说+级以上侠客的少侠，获得参加巅峰论剑的资格。",
	["tid#arena_explain7"]="五行地赛",
	["tid#arena_explain8"]="1.五行地赛每周为一轮，每轮结束时根据结算时的排名发放奖励，并重置积分；\\n\\n2.每轮比赛将选定两个势力为本周参赛势力，本轮中只能使用这两个势力的侠客进行挑战和防守\\n\\n3.新一轮比赛开启后必须进入一次擂台才能获得初期积分并获得排名，初期积分会根据上赛季成绩而有不同\\n\\n4.挑战他人，胜者积分提高，败者积分下降\\n\\n5.每天有免费挑战的机会，免费次数用尽后可以使用元宝购买次数\\n\\n6.每天晚上24时根据当时排名发放每日奖励。\\n\\n7.第1轮比赛结束时，五行地赛排名前100的玩家将获得五行天赛的参赛资格，获得更丰厚的奖励\\n\\n8.从第2轮开始，每轮比赛结束时，五行地赛排名前20的玩家将获得五行天赛的参赛资格，五行天赛排名后20名的玩家将退回到五行地赛；",
	["tid#Fun_Libielou_Name"]="侠客回退",
	["tid#Fun_Libielou_Des"]="1.紫品☆品质以上侠客可以使用归隐。\\n\\n2.归隐侠客将使侠客退至紫品☆，并返还进阶必须消耗的所有侠客和资源。\\n\\n3.如果直接获得紫品☆以上品质侠客，则最多回退至获得时的品阶。\\n\\n4.侠客进阶至彩品后，将无法使用归隐功能，请在进阶时谨慎选择消耗的侠客。",
	["tid#status_1"]="这是一个金属性侠客",
	["tid#status_2"]="这是一个火属性侠客",
	["tid#status_3"]="这是一个木属性侠客",
	["tid#status_4"]="这是一个水属性侠客",
	["tid#status_5"]="这是一个极阳侠客",
	["tid#status_6"]="这是一个至阴侠客",
	["tid#status_7"]="这是一个虚空侠客",
	["tid#herotype1"]="这是一个臂力侠客，造成外功伤害",
	["tid#herotype2"]="这是一个身法侠客，造成外功伤害",
	["tid#herotype3"]="这是一个悟性侠客，造成内功伤害",
	["tid#mystic_1"]="1.在密藏中放入秘籍，即可获得秘籍带来的属性加成或特殊效果；\\n\\n2.秘籍分为4大类型，秘籍只能放入对应类型的栏位中；\\n\\n3.同名秘籍只能同时展示一本，品质不同也不可同时展示；\\n\\n4.所有秘籍都必定属于一个特定套装，同时展示多个相同套装的秘籍，可以额外获得套装加成，同一套装的秘籍数量越多，效果越强。",
	["tid#mystic_2"]="1.可以使用三本同品质秘籍进行参悟，获得更高品质的秘籍；\\n\\n2.作为材料的3本秘籍相同时，必定获得同名高品质秘籍；\\n\\n3.作为材料的3本秘籍不完全相同时，随机获得一本高品质秘籍。",
	["tid#UnionArtifact1"]="祈福",
	["tid#UnionArtifact2"]="1.帮会成员每日可以通过点卯获得祈福点；\\n\\n2.使用祈福点可以任意对不同类型的侠客进行强化，强化进度即时离开帮会也会保留，但是只有加入帮会后才会生效；\\n\\n3.强化完毕一个等级的6个属性后，可以提高强化等级继续强化，强化等级受到帮会等级限制，帮会等级不足时，无法升级；\\n\\n4.加入等级不足的帮会时，祈福属性只能发挥部分效果，且不能继续强化和升级，在帮会提升等级后可以正常强化、升级和发挥效力；\\n\\n5.当成员退出帮会后将失去祈福效果。",
	["tid#rpg_rule1"]="神州探秘",
	["tid#rpg_rule2"]="1.各位帮主可以通过体验神州内的各个侠客小故事获得丰厚奖励；\\n\\n2.神州探秘内的敌人强度会随着少侠成长而变动，但是有能力上限，只会强化到特定程度；\\n\\n3.神州探秘内敌我双方的生命和能量不会自动回复，死亡后无法再次使用，可以重置关卡回复成初始状态；\\n\\n4.神州探秘内的宝藏只能获得一次，但是奇物可以反复获得；\\n\\n5.和场景内的NPC互动，可以了解关卡情报、触发支线任务，请积极和NPC们聊天；\\n\\n6.完成特定事件即可达成对应的结局，结束本次挑战。",
