	["tid#MoneyGuide_1070"]="元宝",
	["tid#MoneyGuide_1104"]="铜币是通用货币,升级侠客强化装备都需要消耗铜币,通过挂机,完成日常任务可获得大量铜币",
	["tid#MoneyGuide_1105"]="阅历可用来提升少侠等级，在历练中可获得阅历",
	["tid#MoneyGuide_1106"]="浓缩了大量天地之气的神奇丹药,侠客提升的必要药品",
	["tid#MoneyGuide_1107"]="元宝是流通于世的最有分量的货币，可用于聚义客栈招募侠客，也可在商会购买急需的物品。",
	["tid#MoneyGuide_1108"]="象征地位和财富，可用于升级vip等级解锁特权",
	["tid#MoneyGuide_1109"]="在闯王宝藏中获得的神秘钱币,可以在闯王商店中用来购买想要的货品",
	["tid#MoneyGuide_1110"]="修为是侠客升级所必需的,可以在侠客升级界面提升侠客等级",
	["tid#MoneyGuide_1111"]="在聚义客栈中进行招募获得，在侠客商店中可以兑换其他物品",
	["tid#MoneyGuide_1112"]="解锁练武场栏位专用资源，可以通过挂机奖励获得。",
	["tid#MoneyGuide_1113"]="CARD = 113, --侠客(带品质的侠客)",
	["tid#MoneyGuide_1114"]="侠客相惜的见证,江湖侠士的馈赠,由好友赠送,可在聚义客栈中使用",
	["tid#MoneyGuide_1115"]="用于在帮会商店购买物品，可通过帮会点卯和帮会争锋获得",
	["tid#MoneyGuide_1116"]="从日常任务和周常任务中获取，可以提升武林行侠令的等级。",
	["tid#MoneyGuide_1117"]="从巅峰帮会战中获取，可以提升江湖行侠令的等级。",
	["tid#MoneyGuide_1118"]="在江湖论剑中获得的货币,可以用来在论剑商店购买东西",
	["tid#MoneyGuide_1120"]="帮会等级提升需要许许多多的帮会建设值,可通过帮会点卯、帮会争锋获得",
	["tid#MoneyGuide_1123"]="可以用来升级琅嬛阁的外功类秘籍的参悟效果",
	["tid#MoneyGuide_1124"]="可以用来升级琅嬛阁的身法类秘籍的参悟效果",
	["tid#MoneyGuide_1125"]="可以用来升级琅嬛阁的内功类秘籍的参悟效果",
	["tid#MoneyGuide_1126"]="可以用来升级琅嬛阁的绝技类秘籍的参悟效果",
	["tid#MoneyGuide_1127"]="可以在帮会祈福中对侠客进行强化",
	["tid#MoneyGuide_1129"]="头像，可在个人信息界面更换",
	["tid#MoneyGuide_1128"]="与侠客之间羁绊的证明，可用以在侠客羁绊界面强化侠客",
	["tid#MoneyGuide_1131"]="追捕盗匪获得的信物，可以在迷踪商店兑换特殊商品",
	["tid#MoneyGuide_1132"]="论剑山庄获得的信物，可以在论剑商店兑换特殊商品",
	["tid#MoneyGuide_1133"]="天下演武中获得的信物，可以在演武商店中兑换商品",
	["tid#MoneyGuide_1134"]="巅峰论剑中获得的信物，可以在演武商店中兑换商品",
	["tid#MoneyGuide_1135"]="巅峰论剑竞猜用的货币，巅峰论剑结束后会转换为等值的巅峰币",
	["tid#MoneyGuide_1136"]="在聚宝山掷骰子或拾取获得的货币，可以在聚宝商店中兑换商品",
	["tid#MoneyGuide_1137"]="可以在头像-代金券商城购买礼包",
	["tid#MoneyGuide_1138"]="五行天赛中获得的信物，可以在论剑商店中兑换商品",
	["tid#MoneyGuide_1139"]="侠客历史培养品阶达到红色以上后，根据其修炼程度获得的修炼奖励，可用于升级上古遗物",
	["tid#MoneyGuide_1140"]="上古留下来的宝物，使用后实力有很大提升",
	["tid#MoneyGuide_1142"]="获得此称号后，可在头像处使用。",
	["tid#MoneyGuide_1144"]="苗疆觅宝中获得的信物，可以在苗疆商店中兑换商品",
	["tid#MoneyGuide_1145"]="苗疆觅宝中获得的信物，可以在苗疆商店中兑换商品",
