	["tid#towertip_01"]="相传墨者世家精通机关术，最鼎盛之时筑建了直入青云的机关要塞——天机楼。后来墨家虽然没落，但天机楼依然矗立，其中秘宝引人争夺。",
	["tid#towerdes_01"]="1.击败当层敌人可获得丰富的通关奖励并爬升至下一层；\\n\\n2.战斗失败时，试着调整一下阵容和站位，或者在布阵界面查看其它玩家的通关录像；\\n\\n3.挑战时，若要挑战的敌人战力过低，会自动跳过这些敌人，快速通关至与玩家实力相仿的层数，且奖励会全数发放；",
