	["tid#ShopPrompt_max"]="商会的商品已达到最高品质",
	["tid#mazedes_0001"]="击败闯王宝藏内的怪物可获得惩恶值，当惩恶值积攒到一定程度时可领取惩恶宝箱，获得大量奖励",
	["itd#towername_01"]="锵鸣金铁",
	["itd#towername_02"]="九天业炎",
	["itd#towername_03"]="万象森罗",
	["itd#towername_04"]="碧海鲸浪",
	["tid#BiographyShowDes_001"]="1.江湖茶馆中会有若干个侠客的传记，只有前置侠客的传记全部完成后，才会解锁下个侠客的传记；\\n\\n2.每个传记会分为若干个章节，只有前置章节内的关卡全部完成后，才会解锁下个章节；\\n\\n3.每个章节又会有若干个关卡，只有完成前置关卡后，才能解锁后续关卡；\\n\\n4.已经通关的关卡可以再次进入回看剧情，但不会再次进入战斗和获得奖励；\\n\\n5.完成指定章节和传记后，可在主界面宝箱处领取丰厚奖励；",
	["itd#gacha_box1"]="每次侠客招募都可以累积招募幸运值，幸运值达到特定数值，即可领取幸运奖励。幸运值累计至500，幸运奖励将会升级",
