	["tid#GuildWar_1"]="报名：\\n\\n1：报名时间：各回合首日0时-23时。\\n\\n2：报名人：所有成员都可报名。\\n\\n3：报名不可撤销。\\n\\n4：报名后23时开始自动匹配对手。\\n\\n战斗：\\n\\n1：防御队伍调整时间：各回合首日23时前。\\n\\n2：战斗时间：各回合第二日0时-23时。\\n\\n3：每个成员最多可以设置三队防守队伍。\\n\\n4：参与帮会默认有帮会成员数量上限3倍的NPC队伍参与防守，帮会成员设置的防守队伍会替代1队NPC队伍参与防御。\\n\\n5：开始匹配后将无法调整防御队伍，所有防御队伍包括NPC队伍，将按照战力自动填入阵地中。\\n\\n6：战斗时间开始后，成员可以任意选择一个敌人的阵地发动攻击。\\n\\n7：战斗前可以选择难度星级，根据星级敌方将获得属性加成。\\n\\n8：如果挑战成功，进攻方可以获得选择星级对应的星星，同时获得挑战奖励。防守方阵地越接近大本营、选择星级越高，获得奖励越多。\\n\\n9：攻击成功时，防守部队将被移除，无法再次被挑战；攻击失败时防守方将重置为挑战前的状态，可以再次被挑战。\\n\\n10：一个阵地所有部队都被击败后，该阵地变为【全灭】状态，相邻的所有阵地都将获得生命、攻击下降5%的负面效果，效果可以叠加。\\n\\n11：进攻部队只能攻击1次，无论胜负，都将无法再次使用。\\n\\n12：首次挑战后，所有进攻队伍的编队将锁定，本轮挑战无法被更改，请在挑战前谨慎编辑。\\n\\n13：可以使用模拟战斗试探敌人虚实，模拟战斗后队伍仍可使用，如果胜利，可以将模拟战结果转为正式结果；模拟战有次数限制，提升特权等级可以增加模拟战次数。\\n\\n结算：\\n\\n1：第二日23时会进行结算，星数高者胜利，如果双方星数相同，都视为失败。\\n\\n赛季：\\n\\n1：10回合为一个赛季。\\n\\n2：赛季结束时，根据参加帮会的星数总和进行排名决定胜负。\\n\\n3：新赛季开始后，所有战绩清零。\\n\\n4：季前赛有排名，但是没有排名奖励和赛季胜负。",
	["tid#GuildWar_2"]="帮会争锋",
	["tid#GuildWar_3"]="本期已经报名成功请静待开战",
	["tid#GuildWar_4"]="本期未报名，无法参加",
