	["tid#GuildWar_6"]="正在清理战场",
	["tid#GuildWar_7"]="报名成功",
	["tid#GuildWar_8"]="匹配中",
	["tid#GuildWar_9"]="击败最多敌人",
	["tid#GuildWar_10"]="没有任何队伍失败",
	["tid#GuildWar_11"]="击败敌人最强",
	["tid#GuildWar_12"]="新赛季尚未开始",
	["tid#GuildWar_13"]="防守队伍已经锁定",
	["tid#Bridge_1"]="1.可以任意选择一个曾经拥有的大侠品质侠客作为缘分侠客，在前缘桥续缘时，出现的侠客必定为缘分侠客。\\n\\n2.续缘有保底，累积续缘达到一定值时必定获得缘分侠客。\\n\\n3.当续缘成功出现缘分侠客时，将重置保底次数。\\n\\n4.更换缘分侠客不会影响保底次数的触发。",
	["tid#FourTowerDes_01"]="四象阵的守卫，携带有强大的奇物。击败后可获得其携带的奇物。",
	["tid#FourTowerDes_02"]="四象阵的首领，不依靠奇物的加成就能拥有极强的战力，将其击败后可以获得大量奖励。",
	["tid#FourTowerDes_03"]="阵眼守卫",
	["tid#FourTowerDes_04"]="四象首领",
	["tid#Gacha_ship_1"]="盗帅迷踪",
	["tid#Gacha_ship_2"]="1.活动期间可以消耗海捕令缉拿盗贼，每次缉拿成功都可以获得随机奖励。\\n\\n2.每抓捕1个盗贼，即可累积1点积分，积分累积到一定程度可以获得对应积分奖励。\\n\\n3.通过积分奖励可能获得盗帅令，可以在盗帅商城内兑换豪华奖励。\\n\\n4.活动会定期重置，重置时会清空累积的盗贼抓捕数量和迷踪商店的商品，但是海捕令和盗帅令数量不会减少，可以放心囤积。",
	["tid#roulette1"]="探宝营地",
	["tid#roulette2"]="摸金探宝",
	["tid#roulette3"]="天官探宝",
	["tid#roulette4"]="1.探宝1次可以随机获取一种物品。\\n\\n2.每次探宝有概率获得幸运奖励，分为大中小吉，可以获得额外奖励。\\n\\n3.大奖只能获得1次，幸运奖励可以无限获得。\\n\\n4.可以刷新奖励重置大奖配置并重新决定幸运奖励方位，免费刷新后需要一定时间才可以获得再次免费刷新的机会。也可以使用元宝刷新。",
