	["tid#Top_Arena_001"]="参赛资格：\n1：天下演武排行榜（跨服）中排名前128名\n2：至少拥有5名红色品质以上的侠客\n3：获得参赛资格的玩家，将在周一0点收到邮件通知\n\n比赛时间：\n1：分组时间为周日24点\n2：小组赛时间为周一24点\n3：周二至周日每天进行一轮淘汰赛，直至决出冠军\n4：参赛成员只有每日6点至23点期间可以调整阵容\n5：每日24点会进行战斗结算，时间为6个小时\n\n小组赛：\n1：参赛玩家会分为32个小组\n2：小组赛期间会与组内其他玩家分别对战一次\n3：胜场数最多的玩家获得出线资格\n4：如果两名玩家胜场相同，会加赛一场，胜者出线\n\n淘汰赛\n1：淘汰赛每日只会进行一轮\n2：淘汰赛两两对战\n3：淘汰赛会在周日决出冠军\n4：剩余两人会加赛一场，决出第三名\n\n比赛规则\n1：只能派遣大侠品质的侠客出场\n2：需要派遣三队侠客出战\n3：战斗将采用车轮战的形式，每轮未阵亡的侠客会保留血量进行下轮战斗\n4：对战双方会分为攻方和守方，当单轮战斗超过90秒时，守方会获得本轮战斗的胜利；\n5：对战双方确定后，会计算双方的综合战力，战力较高的一方为守方，较低的一方为攻方；\n\n参赛奖励\n1：冠军产生后，所有参赛者都能够获得一份奖励\n2：奖励会通过邮件发放\n\n竞猜规则\n1：所有玩家都可以参与巅峰论剑的竞猜活动\n2：在每日进行的所有比赛中随机选择一场作为竞猜比赛\n3：每轮竞猜开始时，所有人都会获得100竞猜币\n4：可以投注任意数量的竞猜币支持其中一方（不能双向选择）\n5：竞猜成功获得1.5倍竞猜币，竞猜失败获得0.5倍竞猜币\n6：巅峰论剑结束后，所有竞猜币会转化为巅峰币\n7：所有奖励均通过邮件发放",
