	["tid#StageName_5060"]="50-60",
	["tid#LegendRule_01"]="1.战斗期间，敌人会不断刷新，直到战斗结束；\n2.在一场战斗中击败敌人的数量达到需求后，下次进入战役时难度会升级；\n3.难度升级后，敌人的血量会增加，难度越高，增加的血量越多；\n4.战斗结束后，会根据战役难度和击败敌人数量进行排名并发放奖励；",
	["tid#LegendRule_02"]="1.战斗期间，每隔一段时间会刷新一波怪物，直到战斗结束；\n2.下一波怪物刷新时，若前一波的怪物没有击败，则怪物会自爆，对周围侠客造成当前剩余血量的伤害；\n3.在一场战斗中的生存时间达到需求后，下次进入战役时难度会升级；\n4.难度升级后，敌人的攻击力会增加，难度越高，增加的攻击力越多；\n5.战斗结束后，会根据战役难度和生存时间进行排名并发放奖励；",
	["tid#LegendRule_03"]="距离难度升级还需击败",
	["tid#LegendRule_04"]="距离难度升级还需生存",
	["tid#LegendRule_05"]="难度已升级！",
	["tid#LegendRule_06"]="已达到最高难度！",
	["tid#LegendRule_07"]="人",
	["tid#LegendRule_08"]="秒",
