	["tid#LegendName_210"]="帝王谷其二·生存",
	["tid#LegendStory_101"]="说是丐唐两帮与明教对阵与枫华谷，要决一生死，以维护武林正道。谁知丐唐之中却早已经出了奸细，形势几番陷入生死存亡。",
	["tid#LegendStory_102"]="龙门之地，恶匪横行，李知傲闻此事前来剿除恶匪。有幸见识了此事的人，说那日的李知傲有如风卷残云扫落叶……",
	["tid#LegendStory_103"]="南疆五仙教，也便是江湖口中的五毒教，出了一个败类流派制作毒傀儡为祸乡间。阿岚奉总教之命，前来肃清教宗，以证五仙圣名。",
	["tid#LegendStory_104"]="逐渐壮大的吐蕃，开始觊觎中原腹地，不停地蚕食着关陇诸城。那一日一处边防要塞再次受到吐蕃的攻击，正当士兵们绝望之时，忽然天降神兵。",
	["tid#LegendStory_105"]="九黎之地有一钟灵毓秀之地，相传这里山中有奇铁之矿，采而炼之可锻造神兵。江湖一伙贼人凭着传说而来想发笔横财，却不知道一但盗采山石会破坏自然生灵的栖息……",
	["tid#LegendStory_106"]="神策军勾结太乙气盘踞华山脚下，为首的奉天韦肆意欺压百姓，竟当着东海少侠的面杀害了华山派宁不凡的青梅竹马。后者闻之大怒，单枪匹马便闯神策营......",
	["tid#LegendStory_107"]="东径关守将不顾同袍安危，擅自收受贿赂讲契丹人放入关内，燕云飞和东海大侠一路追赶，发现那坏事儿的神策中竟有一人让大侠分外熟悉......",
	["tid#LegendStory_108"]="奉天韦在洛阳保全一条性命，逃到了巴陵县。本是强弩之末。他却勾结酷吏，装神弄鬼设法征田，恶事做尽，最终难逃法网。",
	["tid#LegendStory_109"]="周湘君在长安宴请东海侠客，还叫上了贪嘴的陆小遥。本以为一场宴席主宾尽欢，没想到半路杀出群武林高手.....",
	["tid#LegendStory_110"]="电闪雷鸣夜，东海大侠与墨家女孩一起站在一栋古怪楼阁外，狂风破开窗棂，牌匾砰然坠地，上面写得是“机关阁”......",
	["tid#LegendStory_201"]="东海之滨的一个码头上，突然遭遇倭人的袭击，烧杀掳掠是无恶不作。好在长安锦衣司的李郡与其跟班小厮陆小遥来此办事，赶走了这些所图甚广的贼倭人。",
	["tid#LegendStory_202"]="红衣教集结在午阳岗，趁枫华谷战罢的丐唐联军疲惫之时占尽渔翁之利。危亡之际，东海侠与锦衣司李郡共谋一计，便是围魏救赵去攻打红衣圣坛荻花宫。",
	["tid#LegendStory_203"]="一帮图谋不轨的天竺僧突然闯入少林的讲经会。年轻有为的大师清觉本要与这帮宵小辨经说义，却不想自己的堕入魔道的师兄也在其间。",
	["tid#LegendStory_204"]="且说这少室山上，一波未平一波又起，方才赶走了天竺僧，又有神机火营讨人来。带头的红夷军头领王司马，叫嚣着不交出潜藏在少林的薛家军眷属，便要炸平少林。",
	["tid#LegendStory_205"]="原以为贼人在白驼山庄盗走了假典论，便顺着线索一路追到蜀中唐门。却没想到中了贼人的圈套，面对唐门铺天盖地的机关暗器，又是险象环生，惊魂夺魄。",
	["tid#LegendStory_206"]="正逢云州陷落、时局危难。天策林无双调守雁门关。奚人突厥犯境，引得各路高手驰援雁门。没成想，突厥大将是个汉人，正是林无双胞兄，林炎烈。",
	["tid#LegendStory_207"]="东京洛阳瘟疫瘟疫横生，秋值的林无双写信告知东海少侠，让他来暗中调查西京大疫的真正缘由......",
	["tid#LegendStory_208"]="燕山下，戈壁旁，有个世代靠耕种粟黍为生的小村落，东海大侠与形意门靳辰洋穿行戈壁，投宿于此，却没想到这小小村庄竟是个凶险之地......",
	["tid#LegendStory_209"]="东海大侠从中原向西游历，行至关中渭河，在关中偶遇酷爱收集前朝遗物的天师门张天昊和形貌古怪的古墓派翟东玄......",
	["tid#LegendStory_210"]="东海少侠与天师门和古墓派一起击败棺中的“敌人”，得了喘息之机。少侠终于从古墓那里得知了地下世界的秘密......",
	["tid#legend_talk_10101"]="说这丐帮沈念悔恨听谗言，落得如今举目四望无生天。",
	["tid#legend_talk_10102"]="此时唐门小女却相劝，道撑过一时定有人来助援。",
	["tid#legend_talk_10103"]="沈念问可是此前见过的东海侠，唐明月点头便打开了怀中的机关匣。",
	["tid#legend_talk_10104"]="随着机关的里的焰火窜到了九霄上，沈念也誓要将那气势扬。",
	["tid#legend_talk_10105"]="只见沈念挥出了降龙掌，翻身又舞起了打狗棒。",
	["tid#legend_talk_10106"]="几下击退的来犯的明教贼，当此亢龙犹未悔。",
	["tid#legend_talk_10107"]="唐小妹当下也不输阵，机弩暗器堪称神。",
	["tid#legend_talk_10108"]="机关奇术蛇毒蝎，四散派发阎王贴。",
	["tid#legend_talk_10109"]="可寒风萧瑟催黄叶，二人她终于难堪气力竭。",
	["tid#legend_talk_10110"]="这丐唐险些陷入了夺命泽，终于等来了那东海蓬莱客。",
	["tid#legend_talk_10111"]="嚯！那场面！",
	["tid#legend_talk_10112"]="这大侠翻身似飞鹞，闪转腾挪步法妙。",
	["tid#legend_talk_10113"]="凭几番敌手莫近前，众百兵难使剑锋偏。",
	["tid#legend_talk_10114"]="这贼人们束手无计施，眼见都愣在原地呆痴痴。",
	["tid#legend_talk_10115"]="恶贼首怒上心头一声吼，使出那飞沙走石鬼见愁。",
	["tid#legend_talk_10116"]="贼人们刀枪棍棒斧钺叉，大侠们轻松躲闪又招架。",
	["tid#legend_talk_10117"]="大侠们三尺青锋斩乱麻，剑气直穿贼人的铁鳞甲。",
	["tid#legend_talk_10118"]="大侠神勇不可挡，荡！荡尽贼寇无地儿藏！",
	["tid#legend_talk_10119"]="大侠这是打得一拳开,百拳莫敢来。贼人趁乱走，宵小跟头栽。",
	["tid#legend_talk_10120"]="说那东海大侠多正气，凭个侠字走天下，谈笑吓破贼人胆，撩袍归去现潇洒。",
	["tid#legend_talk_10121"]="恶人自以为围住大侠计谋高，没成想大侠三拳两脚就破了招。",
	["tid#legend_talk_10122"]="却说那日夜黑风高贼人走，却被大侠一招擒拿绝寰尘！",
	["tid#legend_talk_10123"]="只听噌噌数下金铁鸣，胜负顷刻即定，少侠这边微丝未动，贼子那头却胆颤心惊。",
	["tid#legend_talk_10124"]="那少侠不与贼人费口舌！剑出鞘，似晨霜，便于长安威名扬！",
	["tid#legend_talk_10125"]="恶人贼首逞凶狂，花拳绣腿使人笑，那大侠只一招，便打得贼首直怪叫。",
	["tid#legend_talk_10126"]="此战一胜定乾坤，侠之大，为国为民护山河。",
	["tid#legend_talk_10127"]="大侠大喝一声，“贼人休走！”看他横眉立眼、目似金星、贯是嫉恶如仇！",
	["tid#legend_talk_10128"]="说时迟，那时快，一面是百道逆潮的八卦掌，一面气吞山河的青锋剑！",
	["tid#legend_talk_10129"]="要说那东海客名堂大，放浪形骸的事儿他不做，江湖哪有危难他便赴风波。",
	["tid#legend_talk_10130"]="各位客官您把坐看，江湖传奇事颇多，咱话一话那位大名鼎鼎蓬莱东海客！",
	["tid#legend_talk_10201"]="那龙门当家上来先是道声好，问李知傲此来啥指教？",
	["tid#legend_talk_10202"]="李知傲沉脸不说话，随手便将宝剑拔。",
	["tid#legend_talk_10203"]="龙门当家也不含糊，唤来群匪齐招呼。",
	["tid#legend_talk_10204"]="李知傲一人独当千夫勇，哪管那群贼气势凶。",
	["tid#legend_talk_10205"]="龙门当家这下可慌了神，连忙向着寨里跑丢魂。",
	["tid#legend_talk_10206"]="要说这巨侠此刻却红了眼，非要进那虎穴龙潭探深浅。",
	["tid#legend_talk_10207"]="谁可知李知傲中了奸人计，这是诱敌深入落网里。",
	["tid#legend_talk_10208"]="匪贼们见了李知傲落圈套，又恢复了先前的气焰狂叫嚣。",
	["tid#legend_talk_10209"]="谁知突然来了个蒙面客，眨眼便将那网绳割。",
	["tid#legend_talk_10210"]="李知傲连忙谢了人搭救，说不除尽这龙门贼人不罢休！",
	["tid#legend_talk_10211"]="嚯！那场面！",
	["tid#legend_talk_10212"]="这大侠翻身似飞鹞，闪转腾挪步法妙。",
	["tid#legend_talk_10213"]="凭几番敌手莫近前，众百兵难使剑锋偏。",
	["tid#legend_talk_10214"]="这贼人们束手无计施，眼见都愣在原地呆痴痴。",
	["tid#legend_talk_10215"]="恶贼首怒上心头一声吼，使出那飞沙走石鬼见愁。",
	["tid#legend_talk_10216"]="贼人们刀枪棍棒斧钺叉，大侠们轻松躲闪又招架。",
	["tid#legend_talk_10217"]="大侠们三尺青锋斩乱麻，剑气直穿贼人的铁鳞甲。",
	["tid#legend_talk_10218"]="大侠神勇不可挡，荡！荡尽贼寇无地儿藏！",
	["tid#legend_talk_10219"]="大侠这是打得一拳开,百拳莫敢来。贼人趁乱走，宵小跟头栽。",
	["tid#legend_talk_10220"]="说那东海大侠多正气，凭个侠字走天下，谈笑吓破贼人胆，撩袍归去现潇洒。",
	["tid#legend_talk_10221"]="恶人自以为围住大侠计谋高，没成想大侠三拳两脚就破了招。",
	["tid#legend_talk_10222"]="却说那日夜黑风高贼人走，却被大侠一招擒拿绝寰尘！",
	["tid#legend_talk_10223"]="只听噌噌数下金铁鸣，胜负顷刻即定，少侠这边微丝未动，贼子那头却胆颤心惊。",
	["tid#legend_talk_10224"]="那少侠不与贼人费口舌！剑出鞘，似晨霜，便于长安威名扬！",
	["tid#legend_talk_10225"]="恶人贼首逞凶狂，花拳绣腿使人笑，那大侠只一招，便打得贼首直怪叫。",
	["tid#legend_talk_10226"]="此战一胜定乾坤，侠之大，为国为民护山河。",
	["tid#legend_talk_10227"]="大侠大喝一声，“贼人休走！”看他横眉立眼、目似金星、贯是嫉恶如仇！",
	["tid#legend_talk_10228"]="说时迟，那时快，一面是百道逆潮的八卦掌，一面气吞山河的青锋剑！",
	["tid#legend_talk_10229"]="要说那东海客名堂大，放浪形骸的事儿他不做，江湖哪有危难他便赴风波。",
	["tid#legend_talk_10230"]="各位客官您把坐看，江湖传奇事颇多，咱话一话那位大名鼎鼎蓬莱东海客！",
	["tid#legend_talk_10301"]="要说这五仙教，深居苗疆瘴毒地，养蛊练毒称第一。",
	["tid#legend_talk_10302"]="可虽说寻常人谈毒就色变，可五仙并无害人意。",
	["tid#legend_talk_10303"]="谁知出了利欲熏心的贼长老，丧尽天良傀儡人，坏了五仙的好名声。",
	["tid#legend_talk_10304"]="他们私掠无辜的老百姓，逼人做工制作毒傀儡。",
	["tid#legend_talk_10305"]="阿岚来到了傀儡巢，无奈用一身本事化解了开门的傀儡潮。",
	["tid#legend_talk_10306"]="那贼长老见敌不过，就盘算着将阿岚往着巢穴深处引。",
	["tid#legend_talk_10307"]="这阿岚也不是莽撞人，表面着了奸人道，一路跟着往里去。",
	["tid#legend_talk_10308"]="可阿岚早就派人堵了奸人的逃跑路，破了贼长老的良上计。",
	["tid#legend_talk_10309"]="这贼人没想到，自己中了连环套，只好跪地来求饶。",
	["tid#legend_talk_10310"]="可阿岚心一横，这样的败类不能留，定要铲除这贼长老。",
	["tid#legend_talk_10311"]="嚯！那场面！",
	["tid#legend_talk_10312"]="这大侠翻身似飞鹞，闪转腾挪步法妙。",
	["tid#legend_talk_10313"]="凭几番敌手莫近前，众百兵难使剑锋偏。",
	["tid#legend_talk_10314"]="这贼人们束手无计施，眼见都愣在原地呆痴痴。",
	["tid#legend_talk_10315"]="恶贼首怒上心头一声吼，使出那飞沙走石鬼见愁。",
	["tid#legend_talk_10316"]="贼人们刀枪棍棒斧钺叉，大侠们轻松躲闪又招架。",
	["tid#legend_talk_10317"]="大侠们三尺青锋斩乱麻，剑气直穿贼人的铁鳞甲。",
	["tid#legend_talk_10318"]="大侠神勇不可挡，荡！荡尽贼寇无地儿藏！",
	["tid#legend_talk_10319"]="大侠这是打得一拳开,百拳莫敢来。贼人趁乱走，宵小跟头栽。",
	["tid#legend_talk_10320"]="说那东海大侠多正气，凭个侠字走天下，谈笑吓破贼人胆，撩袍归去现潇洒。",
	["tid#legend_talk_10321"]="恶人自以为围住大侠计谋高，没成想大侠三拳两脚就破了招。",
	["tid#legend_talk_10322"]="却说那日夜黑风高贼人走，却被大侠一招擒拿绝寰尘！",
	["tid#legend_talk_10323"]="只听噌噌数下金铁鸣，胜负顷刻即定，少侠这边微丝未动，贼子那头却胆颤心惊。",
	["tid#legend_talk_10324"]="那少侠不与贼人费口舌！剑出鞘，似晨霜，便于长安威名扬！",
	["tid#legend_talk_10325"]="恶人贼首逞凶狂，花拳绣腿使人笑，那大侠只一招，便打得贼首直怪叫。",
	["tid#legend_talk_10326"]="此战一胜定乾坤，侠之大，为国为民护山河。",
	["tid#legend_talk_10327"]="大侠大喝一声，“贼人休走！”看他横眉立眼、目似金星、贯是嫉恶如仇！",
	["tid#legend_talk_10328"]="说时迟，那时快，一面是百道逆潮的八卦掌，一面气吞山河的青锋剑！",
	["tid#legend_talk_10329"]="要说那东海客名堂大，放浪形骸的事儿他不做，江湖哪有危难他便赴风波。",
	["tid#legend_talk_10330"]="各位客官您把坐看，江湖传奇事颇多，咱话一话那位大名鼎鼎蓬莱东海客！",
	["tid#legend_talk_10401"]="只见那黄沙漫过几重天，黑云压在古城边。",
	["tid#legend_talk_10402"]="守城的兵将们士气低，看着那即将耗尽的粗粮草，形势已然很危险。",
	["tid#legend_talk_10403"]="就听得一声鹰长鸣，似有那利剑划破了大黑天。",
	["tid#legend_talk_10404"]="几千雄兵从天降，是名唤天鹰的大侠来救场。",
	["tid#legend_talk_10405"]="那天鹰密教方剑斌，击穿了城门边的高原狼。",
	["tid#legend_talk_10406"]="攻城的吐蕃将领心狂妄，只觉得几千援兵不够强。",
	["tid#legend_talk_10407"]="于是他挥手士兵继续上，却哪知他的性命早已不多长。",
	["tid#legend_talk_10408"]="方剑斌吹起了长鹰哨，就见着神鹰向低多盘桓。",
	["tid#legend_talk_10409"]="这神鹰突然盯紧了眼中兔，铁喙化作精钢剑，直直飞向那傲慢的吐蕃将。",
	["tid#legend_talk_10410"]="突然没了带头人，这吐蕃士兵顿时乱成了糊粥汤。",
	["tid#legend_talk_10411"]="嚯！那场面！",
	["tid#legend_talk_10412"]="这大侠翻身似飞鹞，闪转腾挪步法妙。",
	["tid#legend_talk_10413"]="凭几番敌手莫近前，众百兵难使剑锋偏。",
	["tid#legend_talk_10414"]="这贼人们束手无计施，眼见都愣在原地呆痴痴。",
	["tid#legend_talk_10415"]="恶贼首怒上心头一声吼，使出那飞沙走石鬼见愁。",
	["tid#legend_talk_10416"]="贼人们刀枪棍棒斧钺叉，大侠们轻松躲闪又招架。",
	["tid#legend_talk_10417"]="大侠们三尺青锋斩乱麻，剑气直穿贼人的铁鳞甲。",
	["tid#legend_talk_10418"]="大侠神勇不可挡，荡！荡尽贼寇无地儿藏！",
	["tid#legend_talk_10419"]="大侠这是打得一拳开,百拳莫敢来。贼人趁乱走，宵小跟头栽。",
	["tid#legend_talk_10420"]="说那东海大侠多正气，凭个侠字走天下，谈笑吓破贼人胆，撩袍归去现潇洒。",
	["tid#legend_talk_10421"]="恶人自以为围住大侠计谋高，没成想大侠三拳两脚就破了招。",
	["tid#legend_talk_10422"]="却说那日夜黑风高贼人走，却被大侠一招擒拿绝寰尘！",
	["tid#legend_talk_10423"]="只听噌噌数下金铁鸣，胜负顷刻即定，少侠这边微丝未动，贼子那头却胆颤心惊。",
	["tid#legend_talk_10424"]="那少侠不与贼人费口舌！剑出鞘，似晨霜，便于长安威名扬！",
	["tid#legend_talk_10425"]="恶人贼首逞凶狂，花拳绣腿使人笑，那大侠只一招，便打得贼首直怪叫。",
	["tid#legend_talk_10426"]="此战一胜定乾坤，侠之大，为国为民护山河。",
	["tid#legend_talk_10427"]="大侠大喝一声，“贼人休走！”看他横眉立眼、目似金星、贯是嫉恶如仇！",
	["tid#legend_talk_10428"]="说时迟，那时快，一面是百道逆潮的八卦掌，一面气吞山河的青锋剑！",
	["tid#legend_talk_10429"]="要说那东海客名堂大，放浪形骸的事儿他不做，江湖哪有危难他便赴风波。",
	["tid#legend_talk_10430"]="各位客官您把坐看，江湖传奇事颇多，咱话一话那位大名鼎鼎蓬莱东海客！",
	["tid#legend_talk_10501"]="却说那些采石的盗矿贼，斤斧取木毁林山，敲山断石积成磊。",
	["tid#legend_talk_10502"]="可林间生灵苦不迭，奔走逃散事事休。",
	["tid#legend_talk_10503"]="这九黎灵女唤筱九，相传识得鸟兽语。",
	["tid#legend_talk_10504"]="听闻奔走的野兽来诉状，便起身伴着贴身狸奴向贼往。",
	["tid#legend_talk_10505"]="只见筱九舞起了手中杖，这狸奴竟化身斑斓虎。",
	["tid#legend_talk_10506"]="一时跃入贼人中，昂首呼啸震断贼人魂。",
	["tid#legend_talk_10507"]="贼人们一时回过神，便抄起了兵器想抗衡。",
	["tid#legend_talk_10508"]="以为只是寻常虎，利齿难与金铁刀刃相交锋。",
	["tid#legend_talk_10509"]="可叹贪婪又无知的江湖贼，如此恶行须受惩。",
	["tid#legend_talk_10510"]="忽闻一阵鼓声来，群贼们的眼前一片白，一时神魂噩噩皆摇摆。",
	["tid#legend_talk_10511"]="嚯！那场面！",
	["tid#legend_talk_10512"]="这大侠翻身似飞鹞，闪转腾挪步法妙。",
	["tid#legend_talk_10513"]="凭几番敌手莫近前，众百兵难使剑锋偏。",
	["tid#legend_talk_10514"]="这贼人们束手无计施，眼见都愣在原地呆痴痴。",
	["tid#legend_talk_10515"]="恶贼首怒上心头一声吼，使出那飞沙走石鬼见愁。",
	["tid#legend_talk_10516"]="贼人们刀枪棍棒斧钺叉，大侠们轻松躲闪又招架。",
	["tid#legend_talk_10517"]="大侠们三尺青锋斩乱麻，剑气直穿贼人的铁鳞甲。",
	["tid#legend_talk_10518"]="大侠神勇不可挡，荡！荡尽贼寇无地儿藏！",
	["tid#legend_talk_10519"]="大侠这是打得一拳开,百拳莫敢来。贼人趁乱走，宵小跟头栽。",
	["tid#legend_talk_10520"]="说那东海大侠多正气，凭个侠字走天下，谈笑吓破贼人胆，撩袍归去现潇洒。",
	["tid#legend_talk_10521"]="恶人自以为围住大侠计谋高，没成想大侠三拳两脚就破了招。",
	["tid#legend_talk_10522"]="却说那日夜黑风高贼人走，却被大侠一招擒拿绝寰尘！",
	["tid#legend_talk_10523"]="只听噌噌数下金铁鸣，胜负顷刻即定，少侠这边微丝未动，贼子那头却胆颤心惊。",
	["tid#legend_talk_10524"]="那少侠不与贼人费口舌！剑出鞘，似晨霜，便于长安威名扬！",
	["tid#legend_talk_10525"]="恶人贼首逞凶狂，花拳绣腿使人笑，那大侠只一招，便打得贼首直怪叫。",
	["tid#legend_talk_10526"]="此战一胜定乾坤，侠之大，为国为民护山河。",
	["tid#legend_talk_10527"]="大侠大喝一声，“贼人休走！”看他横眉立眼、目似金星、贯是嫉恶如仇！",
	["tid#legend_talk_10528"]="说时迟，那时快，一面是百道逆潮的八卦掌，一面气吞山河的青锋剑！",
	["tid#legend_talk_10529"]="要说那东海客名堂大，放浪形骸的事儿他不做，江湖哪有危难他便赴风波。",
	["tid#legend_talk_10530"]="各位客官您把坐看，江湖传奇事颇多，咱话一话那位大名鼎鼎蓬莱东海客！",
	["tid#legend_talk_10601"]="说华山下，有一鳏夫黄老板，老年得女遂了愿，给妮取名叫灵灵。",
	["tid#legend_talk_10602"]="先三番求神护顺遂，五次拜佛佑她的安宁。",
	["tid#legend_talk_10603"]="灵灵聪明还能干，又助那爹爹将酒店打理得顺心。",
	["tid#legend_talk_10604"]="有一日，那剑宗弟子下了山，自称小侠宁不凡。",
	["tid#legend_talk_10605"]="与那灵灵称兄妹，交游采药情谊深。",
	["tid#legend_talk_10606"]="未曾想，风云不测人遭难，有一只神策余孽，窜到了华山。",
	["tid#legend_talk_10607"]="领头的名叫奉天韦，勾结邪派强征税，欺压百姓意谋反。",
	["tid#legend_talk_10608"]="正赶上东海少侠出手助，贼人歹心未减恶谋生。",
	["tid#legend_talk_10609"]="人群中挑出个黄灵灵，杀鸡儆猴，本想把那英雄气焰灭。",
	["tid#legend_talk_10610"]="却等来宁不凡一声怒吼发冲冠，发誓定要让那血债血来清。",
	["tid#legend_talk_10611"]="嚯！那场面！",
	["tid#legend_talk_10612"]="这大侠翻身似飞鹞，闪转腾挪步法妙。",
	["tid#legend_talk_10613"]="凭几番敌手莫近前，众百兵难使剑锋偏。",
	["tid#legend_talk_10614"]="这贼人们束手无计施，眼见都愣在原地呆痴痴。",
	["tid#legend_talk_10615"]="恶贼首怒上心头一声吼，使出那飞沙走石鬼见愁。",
	["tid#legend_talk_10616"]="贼人们刀枪棍棒斧钺叉，大侠们轻松躲闪又招架。",
	["tid#legend_talk_10617"]="大侠们三尺青锋斩乱麻，剑气直穿贼人的铁鳞甲。",
	["tid#legend_talk_10618"]="大侠神勇不可挡，荡！荡尽贼寇无地儿藏！",
	["tid#legend_talk_10619"]="大侠这是打得一拳开,百拳莫敢来。贼人趁乱走，宵小跟头栽。",
	["tid#legend_talk_10620"]="说那东海大侠多正气，凭个侠字走天下，谈笑吓破贼人胆，撩袍归去现潇洒。",
	["tid#legend_talk_10621"]="恶人自以为围住大侠计谋高，没成想大侠三拳两脚就破了招。",
	["tid#legend_talk_10622"]="却说那日夜黑风高贼人走，却被大侠一招擒拿绝寰尘！",
	["tid#legend_talk_10623"]="只听噌噌数下金铁鸣，胜负顷刻即定，少侠这边微丝未动，贼子那头却胆颤心惊。",
	["tid#legend_talk_10624"]="那少侠不与贼人费口舌！剑出鞘，似晨霜，便于长安威名扬！",
	["tid#legend_talk_10625"]="恶人贼首逞凶狂，花拳绣腿使人笑，那大侠只一招，便打得贼首直怪叫。",
	["tid#legend_talk_10626"]="此战一胜定乾坤，侠之大，为国为民护山河。",
	["tid#legend_talk_10627"]="大侠大喝一声，“贼人休走！”看他横眉立眼、目似金星、贯是嫉恶如仇！",
	["tid#legend_talk_10628"]="说时迟，那时快，一面是百道逆潮的八卦掌，一面气吞山河的青锋剑！",
	["tid#legend_talk_10629"]="要说那东海客名堂大，放浪形骸的事儿他不做，江湖哪有危难他便赴风波。",
	["tid#legend_talk_10630"]="各位客官您把坐看，江湖传奇事颇多，咱话一话那位大名鼎鼎蓬莱东海客！",
	["tid#legend_talk_10701"]="书接上回，守将燕云飞一得边事报，便同东海侠客星夜兼程赴关门。",
	["tid#legend_talk_10702"]="关门下，灯火稀，只听得神策将士推骨牌，还把那个果脯吸？！",
	["tid#legend_talk_10703"]="燕云飞气不打一处出，盾击盾压几来回。",
	["tid#legend_talk_10704"]="锵锵两声兵痞倒，大骂，“谁敢动你神策爷！”",
	["tid#legend_talk_10705"]="燕云飞冷笑几声抽陌刀，刀刃如雪泛寒光。",
	["tid#legend_talk_10706"]="吓得那神策小人一哆嗦，只往领头的身后藏——",
	["tid#legend_talk_10707"]="“您是爷来我是儿，黄金美酒请收好，咱爷俩万万别把和气伤.......”",
	["tid#legend_talk_10708"]="“笑话！”一声呼喊破夜空，烛火都跟着摇三摇。",
	["tid#legend_talk_10709"]="来人正巧非别人，正是那逃了两次的奉天韦！",
	["tid#legend_talk_10710"]="东海侠，欲出招，说一声“燕大哥你往前追，我不擒到这贼人不能回！”",
	["tid#legend_talk_10711"]="嚯！那场面！",
	["tid#legend_talk_10712"]="这大侠翻身似飞鹞，闪转腾挪步法妙。",
	["tid#legend_talk_10713"]="凭几番敌手莫近前，众百兵难使剑锋偏。",
	["tid#legend_talk_10714"]="这贼人们束手无计施，眼见都愣在原地呆痴痴。",
	["tid#legend_talk_10715"]="恶贼首怒上心头一声吼，使出那飞沙走石鬼见愁。",
	["tid#legend_talk_10716"]="贼人们刀枪棍棒斧钺叉，大侠们轻松躲闪又招架。",
	["tid#legend_talk_10717"]="大侠们三尺青锋斩乱麻，剑气直穿贼人的铁鳞甲。",
	["tid#legend_talk_10718"]="大侠神勇不可挡，荡！荡尽贼寇无地儿藏！",
	["tid#legend_talk_10719"]="大侠这是打得一拳开,百拳莫敢来。贼人趁乱走，宵小跟头栽。",
	["tid#legend_talk_10720"]="说那东海大侠多正气，凭个侠字走天下，谈笑吓破贼人胆，撩袍归去现潇洒。",
	["tid#legend_talk_10721"]="恶人自以为围住大侠计谋高，没成想大侠三拳两脚就破了招。",
	["tid#legend_talk_10722"]="却说那日夜黑风高贼人走，却被大侠一招擒拿绝寰尘！",
	["tid#legend_talk_10723"]="只听噌噌数下金铁鸣，胜负顷刻即定，少侠这边微丝未动，贼子那头却胆颤心惊。",
	["tid#legend_talk_10724"]="那少侠不与贼人费口舌！剑出鞘，似晨霜，便于长安威名扬！",
	["tid#legend_talk_10725"]="恶人贼首逞凶狂，花拳绣腿使人笑，那大侠只一招，便打得贼首直怪叫。",
	["tid#legend_talk_10726"]="此战一胜定乾坤，侠之大，为国为民护山河。",
	["tid#legend_talk_10727"]="大侠大喝一声，“贼人休走！”看他横眉立眼、目似金星、贯是嫉恶如仇！",
	["tid#legend_talk_10728"]="说时迟，那时快，一面是百道逆潮的八卦掌，一面气吞山河的青锋剑！",
	["tid#legend_talk_10729"]="要说那东海客名堂大，放浪形骸的事儿他不做，江湖哪有危难他便赴风波。",
	["tid#legend_talk_10730"]="各位客官您把坐看，江湖传奇事颇多，咱话一话那位大名鼎鼎蓬莱东海客！",
	["tid#legend_talk_10801"]="要论巴陵之妙，全在水土富饶，不用靠天来吃饭，丰年家家有余粮。",
	["tid#legend_talk_10802"]="可这自从换了节度使，哎——这个年年都把怪事闹！",
	["tid#legend_talk_10803"]="先是湖边出了青水鬼，吓得李大牛家不敢耕田挥锄刀。",
	["tid#legend_talk_10804"]="再是那山脚来了个白毛妖，又害数亩良田荒废了。",
	["tid#legend_talk_10805"]="僧人做了法事不见好，又请黄冠把那命数瞧。",
	["tid#legend_talk_10806"]="妖魔鬼怪没除尽，幸来了东海的少侠巧把这秘案破——",
	["tid#legend_talk_10807"]="原来哪有什么神和鬼，都是酷吏和神策，想把那个田地的油水捞。",
	["tid#legend_talk_10808"]="奉天韦是抓耳挠腮脚跺地，心说“怎么次次都能遇着你！”",
	["tid#legend_talk_10809"]="“罢了罢了，全是我的霉运到，兄弟们抄家伙，这次定要把仇报！”",
	["tid#legend_talk_10810"]="可没想到，那大侠的身手却是一次更比一次的不得了！",
	["tid#legend_talk_10811"]="嚯！那场面！",
	["tid#legend_talk_10812"]="这大侠翻身似飞鹞，闪转腾挪步法妙。",
	["tid#legend_talk_10813"]="凭几番敌手莫近前，众百兵难使剑锋偏。",
	["tid#legend_talk_10814"]="这贼人们束手无计施，眼见都愣在原地呆痴痴。",
	["tid#legend_talk_10815"]="恶贼首怒上心头一声吼，使出那飞沙走石鬼见愁。",
	["tid#legend_talk_10816"]="贼人们刀枪棍棒斧钺叉，大侠们轻松躲闪又招架。",
	["tid#legend_talk_10817"]="大侠们三尺青锋斩乱麻，剑气直穿贼人的铁鳞甲。",
	["tid#legend_talk_10818"]="大侠神勇不可挡，荡！荡尽贼寇无地儿藏！",
	["tid#legend_talk_10819"]="大侠这是打得一拳开,百拳莫敢来。贼人趁乱走，宵小跟头栽。",
	["tid#legend_talk_10820"]="说那东海大侠多正气，凭个侠字走天下，谈笑吓破贼人胆，撩袍归去现潇洒。",
	["tid#legend_talk_10821"]="恶人自以为围住大侠计谋高，没成想大侠三拳两脚就破了招。",
	["tid#legend_talk_10822"]="却说那日夜黑风高贼人走，却被大侠一招擒拿绝寰尘！",
	["tid#legend_talk_10823"]="只听噌噌数下金铁鸣，胜负顷刻即定，少侠这边微丝未动，贼子那头却胆颤心惊。",
	["tid#legend_talk_10824"]="那少侠不与贼人费口舌！剑出鞘，似晨霜，便于长安威名扬！",
	["tid#legend_talk_10825"]="恶人贼首逞凶狂，花拳绣腿使人笑，那大侠只一招，便打得贼首直怪叫。",
	["tid#legend_talk_10826"]="此战一胜定乾坤，侠之大，为国为民护山河。",
	["tid#legend_talk_10827"]="大侠大喝一声，“贼人休走！”看他横眉立眼、目似金星、贯是嫉恶如仇！",
	["tid#legend_talk_10828"]="说时迟，那时快，一面是百道逆潮的八卦掌，一面气吞山河的青锋剑！",
	["tid#legend_talk_10829"]="要说那东海客名堂大，放浪形骸的事儿他不做，江湖哪有危难他便赴风波。",
	["tid#legend_talk_10830"]="各位客官您把坐看，江湖传奇事颇多，咱话一话那位大名鼎鼎蓬莱东海客！",
	["tid#legend_talk_10901"]="店小二闪身把那位子让，辗转腾挪领着客官进雅房。",
	["tid#legend_talk_10902"]="周庄主这宴席不得了，陆小遥见了眼睛直，大侠险把那个口水掉。",
	["tid#legend_talk_10903"]="别着急，莫着慌，听我给您把那菜名报。",
	["tid#legend_talk_10904"]="轻高面、金乳酥、长生粥后面有甜雪，曼陀香夹饼尝一尝。",
	["tid#legend_talk_10905"]="点心共有十二道，十余品荤素横菜不遑让。",
	["tid#legend_talk_10906"]="有那软牛肠酥油煎，捶打里脊白龙曜，羊肉花丝一寸长，",
	["tid#legend_talk_10907"]="豆苗田鸡唤雪婴，油炸的都叫过门香。",
	["tid#legend_talk_10908"]="主宾三个刚落座，没想到窜出个韦壮武，后面跟着了个胡大壮。",
	["tid#legend_talk_10909"]="白驼的欧阳慧也来串门，都骗这个初出蓬莱的少年郎。",
	["tid#legend_talk_10910"]="说中原吃席规矩多，官高迁来士登科，武人要先比试才能把那筷子捉。",
	["tid#legend_talk_10911"]="嚯！那场面！",
	["tid#legend_talk_10912"]="这大侠翻身似飞鹞，闪转腾挪步法妙。",
	["tid#legend_talk_10913"]="凭几番敌手莫近前，众百兵难使剑锋偏。",
	["tid#legend_talk_10914"]="这贼人们束手无计施，眼见都愣在原地呆痴痴。",
	["tid#legend_talk_10915"]="恶贼首怒上心头一声吼，使出那飞沙走石鬼见愁。",
	["tid#legend_talk_10916"]="贼人们刀枪棍棒斧钺叉，大侠们轻松躲闪又招架。",
	["tid#legend_talk_10917"]="大侠们三尺青锋斩乱麻，剑气直穿贼人的铁鳞甲。",
	["tid#legend_talk_10918"]="大侠神勇不可挡，荡！荡尽贼寇无地儿藏！",
	["tid#legend_talk_10919"]="大侠这是打得一拳开,百拳莫敢来。贼人趁乱走，宵小跟头栽。",
	["tid#legend_talk_10920"]="说那东海大侠多正气，凭个侠字走天下，谈笑吓破贼人胆，撩袍归去现潇洒。",
	["tid#legend_talk_10921"]="恶人自以为围住大侠计谋高，没成想大侠三拳两脚就破了招。",
	["tid#legend_talk_10922"]="却说那日夜黑风高贼人走，却被大侠一招擒拿绝寰尘！",
	["tid#legend_talk_10923"]="只听噌噌数下金铁鸣，胜负顷刻即定，少侠这边微丝未动，贼子那头却胆颤心惊。",
	["tid#legend_talk_10924"]="那少侠不与贼人费口舌！剑出鞘，似晨霜，便于长安威名扬！",
	["tid#legend_talk_10925"]="恶人贼首逞凶狂，花拳绣腿使人笑，那大侠只一招，便打得贼首直怪叫。",
	["tid#legend_talk_10926"]="此战一胜定乾坤，侠之大，为国为民护山河。",
	["tid#legend_talk_10927"]="大侠大喝一声，“贼人休走！”看他横眉立眼、目似金星、贯是嫉恶如仇！",
	["tid#legend_talk_10928"]="说时迟，那时快，一面是百道逆潮的八卦掌，一面气吞山河的青锋剑！",
	["tid#legend_talk_10929"]="要说那东海客名堂大，放浪形骸的事儿他不做，江湖哪有危难他便赴风波。",
	["tid#legend_talk_10930"]="各位客官您把坐看，江湖传奇事颇多，咱话一话那位大名鼎鼎蓬莱东海客！",
	["tid#legend_talk_11001"]="常言道，江湖上擅长机巧有三家，三家宝地有三处：唐门唐家堡，",
	["tid#legend_talk_11002"]="鬼谷八卦阵，墨家机关阁，若不是性命攸关闯不得。",
	["tid#legend_talk_11003"]="说那东海大侠破过了八卦阵，江湖之上把名扬。",
	["tid#legend_talk_11004"]="墨家的女娃娃脾气怪，却也不辞千里把人寻。",
	["tid#legend_talk_11005"]="大侠欲将那原因问，女孩只说破阵之后再与大侠说端详。",
	["tid#legend_talk_11006"]="二人加上那陆小遥，翻山又越水迢迢，终于站在了机关阁的雁回廊。",
	["tid#legend_talk_11007"]="没成想天色忽沉风雨至，不着调的官差陆小遥，又说些走板荒腔调。",
	["tid#legend_talk_11008"]="什么“天机阁原有位半神仙，掌控了着四季风雨同雷电。”",
	["tid#legend_talk_11009"]="墨家女孩连摇头，道是谜底楼里藏。大侠不信神鬼说，率先把这楼阁闯。",
	["tid#legend_talk_11010"]="进去大侠傻了眼，等他的是吱吱呀呀，一波一波，斩不尽的傀儡兵。",
	["tid#legend_talk_11011"]="嚯！那场面！",
	["tid#legend_talk_11012"]="这大侠翻身似飞鹞，闪转腾挪步法妙。",
	["tid#legend_talk_11013"]="凭几番敌手莫近前，众百兵难使剑锋偏。",
	["tid#legend_talk_11014"]="这贼人们束手无计施，眼见都愣在原地呆痴痴。",
	["tid#legend_talk_11015"]="恶贼首怒上心头一声吼，使出那飞沙走石鬼见愁。",
	["tid#legend_talk_11016"]="贼人们刀枪棍棒斧钺叉，大侠们轻松躲闪又招架。",
	["tid#legend_talk_11017"]="大侠们三尺青锋斩乱麻，剑气直穿贼人的铁鳞甲。",
	["tid#legend_talk_11018"]="大侠神勇不可挡，荡！荡尽贼寇无地儿藏！",
	["tid#legend_talk_11019"]="大侠这是打得一拳开,百拳莫敢来。贼人趁乱走，宵小跟头栽。",
	["tid#legend_talk_11020"]="说那东海大侠多正气，凭个侠字走天下，谈笑吓破贼人胆，撩袍归去现潇洒。",
	["tid#legend_talk_11021"]="恶人自以为围住大侠计谋高，没成想大侠三拳两脚就破了招。",
	["tid#legend_talk_11022"]="却说那日夜黑风高贼人走，却被大侠一招擒拿绝寰尘！",
	["tid#legend_talk_11023"]="只听噌噌数下金铁鸣，胜负顷刻即定，少侠这边微丝未动，贼子那头却胆颤心惊。",
	["tid#legend_talk_11024"]="那少侠不与贼人费口舌！剑出鞘，似晨霜，便于长安威名扬！",
	["tid#legend_talk_11025"]="恶人贼首逞凶狂，花拳绣腿使人笑，那大侠只一招，便打得贼首直怪叫。",
	["tid#legend_talk_11026"]="此战一胜定乾坤，侠之大，为国为民护山河。",
	["tid#legend_talk_11027"]="大侠大喝一声，“贼人休走！”看他横眉立眼、目似金星、贯是嫉恶如仇！",
	["tid#legend_talk_11028"]="说时迟，那时快，一面是百道逆潮的八卦掌，一面气吞山河的青锋剑！",
	["tid#legend_talk_11029"]="要说那东海客名堂大，放浪形骸的事儿他不做，江湖哪有危难他便赴风波。",
	["tid#legend_talk_11030"]="各位客官您把坐看，江湖传奇事颇多，咱话一话那位大名鼎鼎蓬莱东海客！",
	["tid#legend_talk_20101"]="锵锵锵，眼见那乌泱泱的倭人杀将来！",
	["tid#legend_talk_20102"]="又见那锦衣官与东海侠，眼看要被贼人们两面夹。",
	["tid#legend_talk_20103"]="东海侠见势道不妙，眼下去寻退贼招。",
	["tid#legend_talk_20104"]="看到了贼船上人数稀，东海侠心里便有了计。",
	["tid#legend_talk_20105"]="趁贼人们贼窝顾不暇，东海侠就放火偷贼家。",
	["tid#legend_talk_20106"]="莫说这放火无仁义，那贼人可畏威不尚礼。",
	["tid#legend_talk_20107"]="又在渔船上见了无名侠，得了诛贼的神刀法。",
	["tid#legend_talk_20108"]="回首却见锦衣小厮报来急，李大人正与那贼头苦相敌。",
	["tid#legend_talk_20109"]="贼头头儿名唤天影丸，刀法阴狠可不一般。",
	["tid#legend_talk_20110"]="东海侠默念现学的杀贼术，只身便将那贼头除。",
	["tid#legend_talk_20111"]="嚯！那场面！",
	["tid#legend_talk_20112"]="这大侠翻身似飞鹞，闪转腾挪步法妙。",
	["tid#legend_talk_20113"]="凭几番敌手莫近前，众百兵难使剑锋偏。",
	["tid#legend_talk_20114"]="这贼人们束手无计施，眼见都愣在原地呆痴痴。",
	["tid#legend_talk_20115"]="恶贼首怒上心头一声吼，使出那飞沙走石鬼见愁。",
	["tid#legend_talk_20116"]="贼人们刀枪棍棒斧钺叉，大侠们轻松躲闪又招架。",
	["tid#legend_talk_20117"]="大侠们三尺青锋斩乱麻，剑气直穿贼人的铁鳞甲。",
	["tid#legend_talk_20118"]="大侠神勇不可挡，荡！荡尽贼寇无地儿藏！",
	["tid#legend_talk_20119"]="大侠这是打得一拳开,百拳莫敢来。贼人趁乱走，宵小跟头栽。",
	["tid#legend_talk_20120"]="说那东海大侠多正气，凭个侠字走天下，谈笑吓破贼人胆，撩袍归去现潇洒。",
	["tid#legend_talk_20121"]="恶人自以为围住大侠计谋高，没成想大侠三拳两脚就破了招。",
	["tid#legend_talk_20122"]="却说那日夜黑风高贼人走，却被大侠一招擒拿绝寰尘！",
	["tid#legend_talk_20123"]="只听噌噌数下金铁鸣，胜负顷刻即定，少侠这边微丝未动，贼子那头却胆颤心惊。",
	["tid#legend_talk_20124"]="那少侠不与贼人费口舌！剑出鞘，似晨霜，便于长安威名扬！",
	["tid#legend_talk_20125"]="恶人贼首逞凶狂，花拳绣腿使人笑，那大侠只一招，便打得贼首直怪叫。",
	["tid#legend_talk_20126"]="此战一胜定乾坤，侠之大，为国为民护山河。",
	["tid#legend_talk_20127"]="大侠大喝一声，“贼人休走！”看他横眉立眼、目似金星、贯是嫉恶如仇！",
	["tid#legend_talk_20128"]="说时迟，那时快，一面是百道逆潮的八卦掌，一面气吞山河的青锋剑！",
	["tid#legend_talk_20129"]="要说那东海客名堂大，放浪形骸的事儿他不做，江湖哪有危难他便赴风波。",
	["tid#legend_talk_20130"]="各位客官您把坐看，江湖传奇事颇多，咱话一话那位大名鼎鼎蓬莱东海客！",
	["tid#legend_talk_20201"]="众人来到了宫门口，解决了守卫就往里走。",
	["tid#legend_talk_20202"]="听闻有不速之人闯圣殿，那红衣圣女挡在了众人前。",
	["tid#legend_talk_20203"]="那圣女自称是月华，问鼠辈们怎敢闯圣坛。",
	["tid#legend_talk_20204"]="只见沈念突然露出些面色寒，那锦衣随身的小厮方才定睛看。",
	["tid#legend_talk_20205"]="那圣女与沈念容貌颇相似，才听得沈念口中唤妹迟。",
	["tid#legend_talk_20206"]="可圣女却突然生出无名火，令左右守卫将来人的性命夺。",
	["tid#legend_talk_20207"]="要说这众侠也不含糊，出招应对来袭的卫教徒。",
	["tid#legend_talk_20208"]="那月华眼见势不妙，吹响了红衣的传音哨。",
	["tid#legend_talk_20209"]="锦衣说围困丐唐的教众要召回，将恋战的沈念往回催。",
	["tid#legend_talk_20210"]="沈念只求要带这圣女回丐帮，东海侠也应下了要帮忙。",
	["tid#legend_talk_20211"]="嚯！那场面！",
	["tid#legend_talk_20212"]="这大侠翻身似飞鹞，闪转腾挪步法妙。",
	["tid#legend_talk_20213"]="凭几番敌手莫近前，众百兵难使剑锋偏。",
	["tid#legend_talk_20214"]="这贼人们束手无计施，眼见都愣在原地呆痴痴。",
	["tid#legend_talk_20215"]="恶贼首怒上心头一声吼，使出那飞沙走石鬼见愁。",
	["tid#legend_talk_20216"]="贼人们刀枪棍棒斧钺叉，大侠们轻松躲闪又招架。",
	["tid#legend_talk_20217"]="大侠们三尺青锋斩乱麻，剑气直穿贼人的铁鳞甲。",
	["tid#legend_talk_20218"]="大侠神勇不可挡，荡！荡尽贼寇无地儿藏！",
	["tid#legend_talk_20219"]="大侠这是打得一拳开,百拳莫敢来。贼人趁乱走，宵小跟头栽。",
