	["tid#legend_talk_20221"]="恶人自以为围住大侠计谋高，没成想大侠三拳两脚就破了招。",
	["tid#legend_talk_20222"]="却说那日夜黑风高贼人走，却被大侠一招擒拿绝寰尘！",
	["tid#legend_talk_20223"]="只听噌噌数下金铁鸣，胜负顷刻即定，少侠这边微丝未动，贼子那头却胆颤心惊。",
	["tid#legend_talk_20224"]="那少侠不与贼人费口舌！剑出鞘，似晨霜，便于长安威名扬！",
	["tid#legend_talk_20225"]="恶人贼首逞凶狂，花拳绣腿使人笑，那大侠只一招，便打得贼首直怪叫。",
	["tid#legend_talk_20226"]="此战一胜定乾坤，侠之大，为国为民护山河。",
	["tid#legend_talk_20227"]="大侠大喝一声，“贼人休走！”看他横眉立眼、目似金星、贯是嫉恶如仇！",
	["tid#legend_talk_20228"]="说时迟，那时快，一面是百道逆潮的八卦掌，一面气吞山河的青锋剑！",
	["tid#legend_talk_20229"]="要说那东海客名堂大，放浪形骸的事儿他不做，江湖哪有危难他便赴风波。",
	["tid#legend_talk_20230"]="各位客官您把坐看，江湖传奇事颇多，咱话一话那位大名鼎鼎蓬莱东海客！",
	["tid#legend_talk_20301"]="今天这少林开坛讲经言，却有不速的番僧扰了清规门。",
	["tid#legend_talk_20302"]="小沙弥以为来了辨经人，忙将法言迎来问。",
	["tid#legend_talk_20303"]="不想这番僧却颇跋扈，连说少林佛浅根基无。",
	["tid#legend_talk_20304"]="众僧起身欲相辩，番僧只说中原无真言。",
	["tid#legend_talk_20305"]="武僧们各个气的青筋抖，倒是这番僧先出手。",
	["tid#legend_talk_20306"]="恰逢清觉方归来，拳打番僧的面门开。",
	["tid#legend_talk_20307"]="本来这些番僧敌不过，气焰消散忙闪躲。",
	["tid#legend_talk_20308"]="可谁知半路杀出个妖僧人，狂刀含血噙利刃。",
	["tid#legend_talk_20309"]="清觉惊呼大师兄，你怎甘堕落成魔佣。",
	["tid#legend_talk_20310"]="这妖僧却自号摩波旬，修的是他化自在天，誓将这少林化为烟。",
	["tid#legend_talk_20311"]="嚯！那场面！",
	["tid#legend_talk_20312"]="这大侠翻身似飞鹞，闪转腾挪步法妙。",
	["tid#legend_talk_20313"]="凭几番敌手莫近前，众百兵难使剑锋偏。",
	["tid#legend_talk_20314"]="这贼人们束手无计施，眼见都愣在原地呆痴痴。",
	["tid#legend_talk_20315"]="恶贼首怒上心头一声吼，使出那飞沙走石鬼见愁。",
	["tid#legend_talk_20316"]="贼人们刀枪棍棒斧钺叉，大侠们轻松躲闪又招架。",
	["tid#legend_talk_20317"]="大侠们三尺青锋斩乱麻，剑气直穿贼人的铁鳞甲。",
	["tid#legend_talk_20318"]="大侠神勇不可挡，荡！荡尽贼寇无地儿藏！",
