	["tid#legend_talk_20324"]="那少侠不与贼人费口舌！剑出鞘，似晨霜，便于长安威名扬！",
	["tid#legend_talk_20325"]="恶人贼首逞凶狂，花拳绣腿使人笑，那大侠只一招，便打得贼首直怪叫。",
	["tid#legend_talk_20326"]="此战一胜定乾坤，侠之大，为国为民护山河。",
	["tid#legend_talk_20327"]="大侠大喝一声，“贼人休走！”看他横眉立眼、目似金星、贯是嫉恶如仇！",
	["tid#legend_talk_20328"]="说时迟，那时快，一面是百道逆潮的八卦掌，一面气吞山河的青锋剑！",
	["tid#legend_talk_20329"]="要说那东海客名堂大，放浪形骸的事儿他不做，江湖哪有危难他便赴风波。",
	["tid#legend_talk_20330"]="各位客官您把坐看，江湖传奇事颇多，咱话一话那位大名鼎鼎蓬莱东海客！",
	["tid#legend_talk_20401"]="彩光金殿起喧闹，见是红夷军的司马在叫嚣。",
	["tid#legend_talk_20402"]="这司马说，早就留了一日给少林把人交，为何如今半个人影瞧不到？",
	["tid#legend_talk_20403"]="原是清觉托了东海侠，昨日便将忠良的薛家村民送山下。",
	["tid#legend_talk_20404"]="见清觉大师不说话，红夷司马只好把话发。",
	["tid#legend_talk_20405"]="唤出了早已待命的神机火营兵，要把这少林的山头都炸平。",
	["tid#legend_talk_20406"]="那锦衣小厮一听慌了神，忙与身旁的东海侠来问。",
	["tid#legend_talk_20407"]="这大师为了保护薛家村，可有什么办法来掌乾坤。",
	["tid#legend_talk_20408"]="清觉此时却无言，合掌闭眼挡在了红夷前。",
	["tid#legend_talk_20409"]="红夷炮却早已对准了金佛殿，见王司马点了火炮的引燃线。",
	["tid#legend_talk_20410"]="可要说这红夷司马火炮似留情，清觉竟毫发无伤现出了不动金身形。",
	["tid#legend_talk_20411"]="嚯！那场面！",
	["tid#legend_talk_20412"]="这大侠翻身似飞鹞，闪转腾挪步法妙。",
	["tid#legend_talk_20413"]="凭几番敌手莫近前，众百兵难使剑锋偏。",
