	["tid#legend_talk_20416"]="贼人们刀枪棍棒斧钺叉，大侠们轻松躲闪又招架。",
	["tid#legend_talk_20417"]="大侠们三尺青锋斩乱麻，剑气直穿贼人的铁鳞甲。",
	["tid#legend_talk_20418"]="大侠神勇不可挡，荡！荡尽贼寇无地儿藏！",
	["tid#legend_talk_20419"]="大侠这是打得一拳开,百拳莫敢来。贼人趁乱走，宵小跟头栽。",
	["tid#legend_talk_20420"]="说那东海大侠多正气，凭个侠字走天下，谈笑吓破贼人胆，撩袍归去现潇洒。",
	["tid#legend_talk_20421"]="恶人自以为围住大侠计谋高，没成想大侠三拳两脚就破了招。",
	["tid#legend_talk_20422"]="却说那日夜黑风高贼人走，却被大侠一招擒拿绝寰尘！",
	["tid#legend_talk_20423"]="只听噌噌数下金铁鸣，胜负顷刻即定，少侠这边微丝未动，贼子那头却胆颤心惊。",
	["tid#legend_talk_20424"]="那少侠不与贼人费口舌！剑出鞘，似晨霜，便于长安威名扬！",
	["tid#legend_talk_20425"]="恶人贼首逞凶狂，花拳绣腿使人笑，那大侠只一招，便打得贼首直怪叫。",
	["tid#legend_talk_20426"]="此战一胜定乾坤，侠之大，为国为民护山河。",
	["tid#legend_talk_20427"]="大侠大喝一声，“贼人休走！”看他横眉立眼、目似金星、贯是嫉恶如仇！",
	["tid#legend_talk_20428"]="说时迟，那时快，一面是百道逆潮的八卦掌，一面气吞山河的青锋剑！",
	["tid#legend_talk_20429"]="要说那东海客名堂大，放浪形骸的事儿他不做，江湖哪有危难他便赴风波。",
	["tid#legend_talk_20430"]="各位客官您把坐看，江湖传奇事颇多，咱话一话那位大名鼎鼎蓬莱东海客！",
	["tid#legend_talk_20501"]="要说这锦衣官，原以为自己是猎人，却不想自己是猎物。",
	["tid#legend_talk_20502"]="原本要把偷书的狐狸捉，到头来自己却成了黄雀口中蝉。",
	["tid#legend_talk_20503"]="白驼的欧阳妹子也来相助，可难挡唐门千奇的机关铺天来。",
	["tid#legend_talk_20504"]="锦衣的小厮陆小遥，见了唐门的明月小妹直咂舌。",
	["tid#legend_talk_20505"]="分明先前还是同敌友，而今到刀剑相向挥矛戈。",
	["tid#legend_talk_20506"]="先前见识过唐小妹的奇弩射，东海侠此时也心忐忑。",
	["tid#legend_talk_20507"]="说这明枪容易躲，暗箭可难防，这唐家堡主城府深得难测量。",
	["tid#legend_talk_20508"]="可如今到了这天罗网，硬着头皮也得闯一闯。",
	["tid#legend_talk_20509"]="锦衣闻言使出了擒拿手，破开了贼人围起的机关阵。",
	["tid#legend_talk_20510"]="道今日一定带着大家逃出这黄泉路！",
	["tid#legend_talk_20511"]="嚯！那场面！",
	["tid#legend_talk_20512"]="这大侠翻身似飞鹞，闪转腾挪步法妙。",
	["tid#legend_talk_20513"]="凭几番敌手莫近前，众百兵难使剑锋偏。",
	["tid#legend_talk_20514"]="这贼人们束手无计施，眼见都愣在原地呆痴痴。",
	["tid#legend_talk_20515"]="恶贼首怒上心头一声吼，使出那飞沙走石鬼见愁。",
	["tid#legend_talk_20516"]="贼人们刀枪棍棒斧钺叉，大侠们轻松躲闪又招架。",
	["tid#legend_talk_20517"]="大侠们三尺青锋斩乱麻，剑气直穿贼人的铁鳞甲。",
	["tid#legend_talk_20518"]="大侠神勇不可挡，荡！荡尽贼寇无地儿藏！",
	["tid#legend_talk_20519"]="大侠这是打得一拳开,百拳莫敢来。贼人趁乱走，宵小跟头栽。",
	["tid#legend_talk_20520"]="说那东海大侠多正气，凭个侠字走天下，谈笑吓破贼人胆，撩袍归去现潇洒。",
	["tid#legend_talk_20521"]="恶人自以为围住大侠计谋高，没成想大侠三拳两脚就破了招。",
	["tid#legend_talk_20522"]="却说那日夜黑风高贼人走，却被大侠一招擒拿绝寰尘！",
	["tid#legend_talk_20523"]="只听噌噌数下金铁鸣，胜负顷刻即定，少侠这边微丝未动，贼子那头却胆颤心惊。",
	["tid#legend_talk_20524"]="那少侠不与贼人费口舌！剑出鞘，似晨霜，便于长安威名扬！",
	["tid#legend_talk_20525"]="恶人贼首逞凶狂，花拳绣腿使人笑，那大侠只一招，便打得贼首直怪叫。",
	["tid#legend_talk_20526"]="此战一胜定乾坤，侠之大，为国为民护山河。",
	["tid#legend_talk_20527"]="大侠大喝一声，“贼人休走！”看他横眉立眼、目似金星、贯是嫉恶如仇！",
	["tid#legend_talk_20528"]="说时迟，那时快，一面是百道逆潮的八卦掌，一面气吞山河的青锋剑！",
	["tid#legend_talk_20529"]="要说那东海客名堂大，放浪形骸的事儿他不做，江湖哪有危难他便赴风波。",
	["tid#legend_talk_20530"]="各位客官您把坐看，江湖传奇事颇多，咱话一话那位大名鼎鼎蓬莱东海客！",
	["tid#legend_talk_20601"]="话说那雁门关上，此时是站满了英雄好汉。",
	["tid#legend_talk_20602"]="只等那守关大将一声令下，便去将那贼人命讨！",
	["tid#legend_talk_20603"]="怪就怪在那守关大将林无双，沉默不语；东海来的少侠，神情紧张。",
	["tid#legend_talk_20604"]="箭楼击鼓共六声，三声慢又三声忙，听得角声阵阵诉豪肠。",
	["tid#legend_talk_20605"]="人群中忽一壮士高喊：林将军！为何还不下令？！",
	["tid#legend_talk_20606"]="林无双手执靠旗，扬向北方。所指处，突厥正集兵一处，刃露寒芒。",
	["tid#legend_talk_20607"]="世人皆以为她顾及兄妹情深，不忍用兵，却不知她实则另有所想。",
	["tid#legend_talk_20608"]="话昔日，那林家兄妹尚小时，最爱拿兵俑沙盘演武。",
	["tid#legend_talk_20609"]="哥哥常征调兵士，猛攻一处；妹妹却早懂分散人马，学那狼咬鹰扬。",
	["tid#legend_talk_20610"]="众英雄得了号令，出关应敌；雄关山壑中亦有无数将士，有如天降！",
	["tid#legend_talk_20611"]="嚯！那场面！",
	["tid#legend_talk_20612"]="这大侠翻身似飞鹞，闪转腾挪步法妙。",
	["tid#legend_talk_20613"]="凭几番敌手莫近前，众百兵难使剑锋偏。",
	["tid#legend_talk_20614"]="这贼人们束手无计施，眼见都愣在原地呆痴痴。",
	["tid#legend_talk_20615"]="恶贼首怒上心头一声吼，使出那飞沙走石鬼见愁。",
	["tid#legend_talk_20616"]="贼人们刀枪棍棒斧钺叉，大侠们轻松躲闪又招架。",
	["tid#legend_talk_20617"]="大侠们三尺青锋斩乱麻，剑气直穿贼人的铁鳞甲。",
	["tid#legend_talk_20618"]="大侠神勇不可挡，荡！荡尽贼寇无地儿藏！",
	["tid#legend_talk_20619"]="大侠这是打得一拳开,百拳莫敢来。贼人趁乱走，宵小跟头栽。",
	["tid#legend_talk_20620"]="说那东海大侠多正气，凭个侠字走天下，谈笑吓破贼人胆，撩袍归去现潇洒。",
	["tid#legend_talk_20621"]="恶人自以为围住大侠计谋高，没成想大侠三拳两脚就破了招。",
	["tid#legend_talk_20622"]="却说那日夜黑风高贼人走，却被大侠一招擒拿绝寰尘！",
	["tid#legend_talk_20623"]="只听噌噌数下金铁鸣，胜负顷刻即定，少侠这边微丝未动，贼子那头却胆颤心惊。",
	["tid#legend_talk_20624"]="那少侠不与贼人费口舌！剑出鞘，似晨霜，便于长安威名扬！",
	["tid#legend_talk_20625"]="恶人贼首逞凶狂，花拳绣腿使人笑，那大侠只一招，便打得贼首直怪叫。",
	["tid#legend_talk_20626"]="此战一胜定乾坤，侠之大，为国为民护山河。",
	["tid#legend_talk_20627"]="大侠大喝一声，“贼人休走！”看他横眉立眼、目似金星、贯是嫉恶如仇！",
	["tid#legend_talk_20628"]="说时迟，那时快，一面是百道逆潮的八卦掌，一面气吞山河的青锋剑！",
	["tid#legend_talk_20629"]="要说那东海客名堂大，放浪形骸的事儿他不做，江湖哪有危难他便赴风波。",
	["tid#legend_talk_20630"]="各位客官您把坐看，江湖传奇事颇多，咱话一话那位大名鼎鼎蓬莱东海客！",
	["tid#legend_talk_20701"]="当时是，东京城内斜阳沉，大疫横行妖疠纷。",
	["tid#legend_talk_20702"]="眼见家家闭门恐慌起，林无双急忙谴人请高人。",
	["tid#legend_talk_20703"]="为救百姓费周章，丹丸涂门人人惧，窗棂犹要点艾香。",
	["tid#legend_talk_20704"]="偏要论：这大疫之中见人性——不少招摇撞骗者，",
	["tid#legend_talk_20705"]="亦有人，见风使舵那个赚钱忙。",
	["tid#legend_talk_20706"]="大疫来的“轻松”祛之难，就连那大名鼎鼎的药王都险些没了方。",
	["tid#legend_talk_20707"]="他早料到，天灾背后有人祸，联手东海来的侠客把那投毒的凶手捉。",
	["tid#legend_talk_20708"]="贼人正是奉天韦，大侠见了他就直跺脚，贼人却想拉拢药王逞猖狂。",
	["tid#legend_talk_20709"]="那药王不慌不忙把酒壶摇，“黄毛小儿我信你？”",
	["tid#legend_talk_20710"]="“那真是白白费了我这一把子岁数与道行！”",
	["tid#legend_talk_20711"]="嚯！那场面！",
	["tid#legend_talk_20712"]="这大侠翻身似飞鹞，闪转腾挪步法妙。",
	["tid#legend_talk_20713"]="凭几番敌手莫近前，众百兵难使剑锋偏。",
	["tid#legend_talk_20714"]="这贼人们束手无计施，眼见都愣在原地呆痴痴。",
	["tid#legend_talk_20715"]="恶贼首怒上心头一声吼，使出那飞沙走石鬼见愁。",
	["tid#legend_talk_20716"]="贼人们刀枪棍棒斧钺叉，大侠们轻松躲闪又招架。",
	["tid#legend_talk_20717"]="大侠们三尺青锋斩乱麻，剑气直穿贼人的铁鳞甲。",
	["tid#legend_talk_20718"]="大侠神勇不可挡，荡！荡尽贼寇无地儿藏！",
	["tid#legend_talk_20719"]="大侠这是打得一拳开,百拳莫敢来。贼人趁乱走，宵小跟头栽。",
	["tid#legend_talk_20720"]="说那东海大侠多正气，凭个侠字走天下，谈笑吓破贼人胆，撩袍归去现潇洒。",
	["tid#legend_talk_20721"]="恶人自以为围住大侠计谋高，没成想大侠三拳两脚就破了招。",
	["tid#legend_talk_20722"]="却说那日夜黑风高贼人走，却被大侠一招擒拿绝寰尘！",
	["tid#legend_talk_20723"]="只听噌噌数下金铁鸣，胜负顷刻即定，少侠这边微丝未动，贼子那头却胆颤心惊。",
	["tid#legend_talk_20724"]="那少侠不与贼人费口舌！剑出鞘，似晨霜，便于长安威名扬！",
	["tid#legend_talk_20725"]="恶人贼首逞凶狂，花拳绣腿使人笑，那大侠只一招，便打得贼首直怪叫。",
	["tid#legend_talk_20726"]="此战一胜定乾坤，侠之大，为国为民护山河。",
	["tid#legend_talk_20727"]="大侠大喝一声，“贼人休走！”看他横眉立眼、目似金星、贯是嫉恶如仇！",
	["tid#legend_talk_20728"]="说时迟，那时快，一面是百道逆潮的八卦掌，一面气吞山河的青锋剑！",
	["tid#legend_talk_20729"]="要说那东海客名堂大，放浪形骸的事儿他不做，江湖哪有危难他便赴风波。",
	["tid#legend_talk_20730"]="各位客官您把坐看，江湖传奇事颇多，咱话一话那位大名鼎鼎蓬莱东海客！",
	["tid#legend_talk_20801"]="远古的夷民心智似幼童，常把那祖先事迹当传说讲。",
	["tid#legend_talk_20802"]="说那突厥贼人祖上并非人，鞑靼祭的是白鹿与苍狼。",
	["tid#legend_talk_20803"]="说这大侠同友人穿戈壁，旅途苦长，傍晚就借宿在了小村庄。",
	["tid#legend_talk_20804"]="小村庄甚奇怪，名字不因山来不靠水，更没有一家姓氏把家当。",
	["tid#legend_talk_20805"]="大侠们住在了村东头，一间破庙见圆月，枭鸣几声令人慌。",
	["tid#legend_talk_20806"]="幸好同行者除了陆小遥，还一位形意门高手能把这个忙来帮。",
	["tid#legend_talk_20807"]="三人挤在村东庙，忽听到，群狐奸笑众狼嚎。",
	["tid#legend_talk_20808"]="陆小遥说起了神鬼事，“这两家姓氏多古怪，这胡通狐来符离为狼。”",
	["tid#legend_talk_20809"]="形意门高手听罢应身起，“哼，管它什么妖和鬼，来了就有这拳头尝。”",
	["tid#legend_talk_20810"]="东海客，探端倪，原是刁民想劫路人财，虽无妖魔，却难逃恶战一场。",
	["tid#legend_talk_20811"]="嚯！那场面！",
	["tid#legend_talk_20812"]="这大侠翻身似飞鹞，闪转腾挪步法妙。",
	["tid#legend_talk_20813"]="凭几番敌手莫近前，众百兵难使剑锋偏。",
	["tid#legend_talk_20814"]="这贼人们束手无计施，眼见都愣在原地呆痴痴。",
	["tid#legend_talk_20815"]="恶贼首怒上心头一声吼，使出那飞沙走石鬼见愁。",
	["tid#legend_talk_20816"]="贼人们刀枪棍棒斧钺叉，大侠们轻松躲闪又招架。",
	["tid#legend_talk_20817"]="大侠们三尺青锋斩乱麻，剑气直穿贼人的铁鳞甲。",
	["tid#legend_talk_20818"]="大侠神勇不可挡，荡！荡尽贼寇无地儿藏！",
	["tid#legend_talk_20819"]="大侠这是打得一拳开,百拳莫敢来。贼人趁乱走，宵小跟头栽。",
	["tid#legend_talk_20820"]="说那东海大侠多正气，凭个侠字走天下，谈笑吓破贼人胆，撩袍归去现潇洒。",
	["tid#legend_talk_20821"]="恶人自以为围住大侠计谋高，没成想大侠三拳两脚就破了招。",
	["tid#legend_talk_20822"]="却说那日夜黑风高贼人走，却被大侠一招擒拿绝寰尘！",
	["tid#legend_talk_20823"]="只听噌噌数下金铁鸣，胜负顷刻即定，少侠这边微丝未动，贼子那头却胆颤心惊。",
	["tid#legend_talk_20824"]="那少侠不与贼人费口舌！剑出鞘，似晨霜，便于长安威名扬！",
	["tid#legend_talk_20825"]="恶人贼首逞凶狂，花拳绣腿使人笑，那大侠只一招，便打得贼首直怪叫。",
	["tid#legend_talk_20826"]="此战一胜定乾坤，侠之大，为国为民护山河。",
	["tid#legend_talk_20827"]="大侠大喝一声，“贼人休走！”看他横眉立眼、目似金星、贯是嫉恶如仇！",
	["tid#legend_talk_20828"]="说时迟，那时快，一面是百道逆潮的八卦掌，一面气吞山河的青锋剑！",
	["tid#legend_talk_20829"]="要说那东海客名堂大，放浪形骸的事儿他不做，江湖哪有危难他便赴风波。",
	["tid#legend_talk_20830"]="各位客官您把坐看，江湖传奇事颇多，咱话一话那位大名鼎鼎蓬莱东海客！",
	["tid#legend_talk_20901"]="少侠打马行至关中，系马岸边远望疆土，远处，土陵连片风光好，",
	["tid#legend_talk_20902"]="两个熟人映眼帘：一位富可敌国的张少爷，一位身负机巧的翟东玄。",
	["tid#legend_talk_20903"]="天师门端手不说话，古墓的笑容森森令人慌。",
	["tid#legend_talk_20904"]="二人半天说原委，原来关中地下，王陵无数，大把的宝物墓中藏！",
	["tid#legend_talk_20905"]="古墓咧嘴邀请少侠去，少侠说这伤天害理有违祖训。",
	["tid#legend_talk_20906"]="天师一拳擂树，愤愤说“我不偷来又不抢！你何故要栽赃！”",
	["tid#legend_talk_20907"]="古墓将背上机巧轻开启，景象吓了大侠一踉跄，原是漫天星斗棺中现！",
	["tid#legend_talk_20908"]="古墓入棺就没了人影，半晌才把声来传，“少侠，这地下银河就是九泉，”",
	["tid#legend_talk_20909"]="“你若奇莫干等，来这棺中悟玄机，地下敌人颇难缠，多个好手更心安“",
	["tid#legend_talk_20910"]="少侠翻身进棺椁，不想敌人在眼前，不知是何妖鬼怪，先运功把那拳脚展！",
	["tid#legend_talk_20911"]="嚯！那场面！",
	["tid#legend_talk_20912"]="这大侠翻身似飞鹞，闪转腾挪步法妙。",
	["tid#legend_talk_20913"]="凭几番敌手莫近前，众百兵难使剑锋偏。",
	["tid#legend_talk_20914"]="这贼人们束手无计施，眼见都愣在原地呆痴痴。",
	["tid#legend_talk_20915"]="恶贼首怒上心头一声吼，使出那飞沙走石鬼见愁。",
	["tid#legend_talk_20916"]="贼人们刀枪棍棒斧钺叉，大侠们轻松躲闪又招架。",
	["tid#legend_talk_20917"]="大侠们三尺青锋斩乱麻，剑气直穿贼人的铁鳞甲。",
	["tid#legend_talk_20918"]="大侠神勇不可挡，荡！荡尽贼寇无地儿藏！",
	["tid#legend_talk_20919"]="大侠这是打得一拳开,百拳莫敢来。贼人趁乱走，宵小跟头栽。",
	["tid#legend_talk_20920"]="说那东海大侠多正气，凭个侠字走天下，谈笑吓破贼人胆，撩袍归去现潇洒。",
	["tid#legend_talk_20921"]="恶人自以为围住大侠计谋高，没成想大侠三拳两脚就破了招。",
	["tid#legend_talk_20922"]="却说那日夜黑风高贼人走，却被大侠一招擒拿绝寰尘！",
	["tid#legend_talk_20923"]="只听噌噌数下金铁鸣，胜负顷刻即定，少侠这边微丝未动，贼子那头却胆颤心惊。",
	["tid#legend_talk_20924"]="那少侠不与贼人费口舌！剑出鞘，似晨霜，便于长安威名扬！",
	["tid#legend_talk_20925"]="恶人贼首逞凶狂，花拳绣腿使人笑，那大侠只一招，便打得贼首直怪叫。",
	["tid#legend_talk_20926"]="此战一胜定乾坤，侠之大，为国为民护山河。",
	["tid#legend_talk_20927"]="大侠大喝一声，“贼人休走！”看他横眉立眼、目似金星、贯是嫉恶如仇！",
	["tid#legend_talk_20928"]="说时迟，那时快，一面是百道逆潮的八卦掌，一面气吞山河的青锋剑！",
	["tid#legend_talk_20929"]="要说那东海客名堂大，放浪形骸的事儿他不做，江湖哪有危难他便赴风波。",
	["tid#legend_talk_20930"]="各位客官您把坐看，江湖传奇事颇多，咱话一话那位大名鼎鼎蓬莱东海客！",
	["tid#legend_talk_21001"]="“地上地下似双生，只不过天地都倒过来，正所谓天上银河地九泉。”",
	["tid#legend_talk_21002"]="当年她发妻的魂灵由此招，那棺椁便是往向冥界之通道。",
	["tid#legend_talk_21003"]="少侠又问这天师为何来，古墓仰头哈哈敞声笑。",
	["tid#legend_talk_21004"]="“少爷平素爱集这陶瓦罐儿，偏要让我带他来探个端详。”",
	["tid#legend_talk_21005"]="他说毕，看远方，远方的星宿岿不动，夕阳杳杳，日暮之景万年长。",
	["tid#legend_talk_21006"]="夕阳中，一座座封土高台平地起。忽听那少侠惊呼一声“我悟了。”",
	["tid#legend_talk_21007"]="“若说此处天上是九泉，那眼前座座高台，便是埋棺的土坑把个儿倒！”",
	["tid#legend_talk_21008"]="天师的少爷头频点，古墓指了指大侠说：“你这小子悟性不得了。”",
	["tid#legend_talk_21009"]="“方才敌人正是地下的陶兵俑。事死者，如事生，看守着珍奇与财宝。”",
	["tid#legend_talk_21010"]="“好家伙，倒了霉，正说谁呢谁便来！闲聊放罢，先把手头的家伙抄！”",
	["tid#legend_talk_21011"]="嚯！那场面！",
	["tid#legend_talk_21012"]="这大侠翻身似飞鹞，闪转腾挪步法妙。",
	["tid#legend_talk_21013"]="凭几番敌手莫近前，众百兵难使剑锋偏。",
	["tid#legend_talk_21014"]="这贼人们束手无计施，眼见都愣在原地呆痴痴。",
	["tid#legend_talk_21015"]="恶贼首怒上心头一声吼，使出那飞沙走石鬼见愁。",
	["tid#legend_talk_21016"]="贼人们刀枪棍棒斧钺叉，大侠们轻松躲闪又招架。",
	["tid#legend_talk_21017"]="大侠们三尺青锋斩乱麻，剑气直穿贼人的铁鳞甲。",
	["tid#legend_talk_21018"]="大侠神勇不可挡，荡！荡尽贼寇无地儿藏！",
	["tid#legend_talk_21019"]="大侠这是打得一拳开,百拳莫敢来。贼人趁乱走，宵小跟头栽。",
	["tid#legend_talk_21020"]="说那东海大侠多正气，凭个侠字走天下，谈笑吓破贼人胆，撩袍归去现潇洒。",
	["tid#legend_talk_21021"]="恶人自以为围住大侠计谋高，没成想大侠三拳两脚就破了招。",
	["tid#legend_talk_21022"]="却说那日夜黑风高贼人走，却被大侠一招擒拿绝寰尘！",
	["tid#legend_talk_21023"]="只听噌噌数下金铁鸣，胜负顷刻即定，少侠这边微丝未动，贼子那头却胆颤心惊。",
	["tid#legend_talk_21024"]="那少侠不与贼人费口舌！剑出鞘，似晨霜，便于长安威名扬！",
	["tid#legend_talk_21025"]="恶人贼首逞凶狂，花拳绣腿使人笑，那大侠只一招，便打得贼首直怪叫。",
	["tid#legend_talk_21026"]="此战一胜定乾坤，侠之大，为国为民护山河。",
	["tid#legend_talk_21027"]="大侠大喝一声，“贼人休走！”看他横眉立眼、目似金星、贯是嫉恶如仇！",
	["tid#legend_talk_21028"]="说时迟，那时快，一面是百道逆潮的八卦掌，一面气吞山河的青锋剑！",
	["tid#legend_talk_21029"]="要说那东海客名堂大，放浪形骸的事儿他不做，江湖哪有危难他便赴风波。",
	["tid#legend_talk_21030"]="各位客官您把坐看，江湖传奇事颇多，咱话一话那位大名鼎鼎蓬莱东海客！",
	["tid#legend_talk_40101"]="这谷中当此时，正是那清风吹叶冷，枫华映血红。",
	["tid#legend_talk_40102"]="这一番鏖战，必是要有些内功强劲，外防严密的侠客方能活。",
	["tid#legend_talk_40201"]="说是那李知傲来到了龙门寨，龙门的当家把他心思猜。",
	["tid#legend_talk_40202"]="李知傲也心想，对付这恶匪不容易，得多几个敏捷的帮手来助力。",
	["tid#legend_talk_40301"]="却说这五仙圣教的圣蝎阿岚，循着线索找到了傀儡人的老巢。",
	["tid#legend_talk_40302"]="看着这令人作呕的毒傀儡，除尽他们可需要多些群攻的大侠来相助。",
	["tid#legend_talk_40401"]="却说吐蕃打到了城防边，守城的士兵在心里求神仙。",
	["tid#legend_talk_40402"]="面对着汪洋的吐蕃兵，要有群攻善战的大侠天降才能行。",
	["tid#legend_talk_40501"]="说那些贪婪的江湖人，将九黎的百兽万灵相驱离。",
	["tid#legend_talk_40502"]="为保卫生灵的栖息地，可求助擅长群攻的侠客们来杀敌。",
	["tid#legend_talk_40601"]="雾山脚下愁云歇，得见华山宁不凡，那宁不凡袖中清风丈三尺，只为友人平血冤。",
	["tid#legend_talk_40602"]="神策军有太乙气宗助阵，木属相的侠士可能能与其相克。",
	["tid#legend_talk_40701"]="说那神策做乱中原后，又在东径关添倒忙，可耻可恨，可耻可恨呐！",
	["tid#legend_talk_40702"]="神策军龟缩不出，火属性的侠士方能克敌制胜。",
	["tid#legend_talk_40801"]="话说那巴陵奇案，真可谓一波三折，谜底揭晓，客官您请听好！",
	["tid#legend_talk_40802"]="神策个个都是脚底抹油的家伙，善于控制木属相侠客更能占得先机。",
	["tid#legend_talk_40901"]="说那一桌玉盘珍羞滋味妙，引得过路食客高手来讨教。",
	["tid#legend_talk_40902"]="宴席味道太诱人，经常用毒导致鼻子不好的水属相侠客更能抵挡诱惑",
	["tid#legend_talk_41001"]="咔啦惊雷响，滋溜闪电窜，东海大侠作镇静，迈步跨过了破门槛。",
	["tid#legend_talk_41002"]="机关阁内暗藏强敌，大侠为稳妥可选择先手控制的木属相侠士助阵。",
	["tid#legend_talk_41101"]="却说那锦衣官李郡横刀立当中，面对那来犯的倭贼气势凶。",
	["tid#legend_talk_41102"]="又说要将那倭人诛，身手敏捷的大侠不可缺。",
	["tid#legend_talk_41201"]="说是那东海侠与众人匿行踪，一路来到了荻花宫。",
	["tid#legend_talk_41202"]="锦衣官说此事要速解决，各位英豪行动要多敏捷。",
	["tid#legend_talk_41301"]="东海侠随清觉大师来到了少室山，不曾想，却瞧见了番僧们来捣乱。",
	["tid#legend_talk_41302"]="要说对付如何这些天竺僧，得多些守卫的铁布衫。",
	["tid#legend_talk_41401"]="要说这朝中奸佞害忠良，忠良的眷属只好躲在了嵩山上。",
	["tid#legend_talk_41402"]="可面对带炮的神火营，要有些外功强劲的大侠才能行。",
	["tid#legend_talk_41501"]="说东海侠与锦衣司的李郡和小厮，一路追到了蜀中唐门夜半时。",
	["tid#legend_talk_41502"]="要说月黑风高可不安全，得多些内功强劲得大侠来支援。",
	["tid#legend_talk_41601"]="常言世上无不亡之国，但逢风雨飘摇际，却难少世出英雄，义赴国难。",
	["tid#legend_talk_41602"]="突厥贼人来势汹汹，雁门雄关奇绝，金属相的侠客精于防守之道，更能派上用场。",
	["tid#legend_talk_41701"]="少侠启信，只见信上印着天策府将印，“大侠敬启，近日西京之困......”",
	["tid#legend_talk_41702"]="西京瘟疫甚嚣，许多水属相侠客惯常应对此种局面，可谴他们上场。",
	["tid#legend_talk_41801"]="说那戈壁边双姓村世代躬耕粟与黍，村民有两姓一姓符来一姓胡。",
	["tid#legend_talk_41802"]="双姓村中居民个个狼顾虎视，需善于防守的金属相侠士方能招架",
	["tid#legend_talk_41901"]="星垂关中沃野阔，月生井鬼渭河流，大侠正游历，路遇相熟者...",
	["tid#legend_talk_41902"]="和天师古墓同行，前方定凶险异常，敢打干杀的火属相门派更为稳妥。",
	["tid#legend_talk_42001"]="各位看官书接上回，这大侠刚把气喘匀，便把这地下的奥妙问——",
	["tid#legend_talk_42002"]="少侠与地下敌人交过手，又知晓这水属相的侠客更能应对此种战斗。",
	["tid#legend_talk_90101"]="且慢！！！",
	["tid#legend_talk_90102"]="只见大侠反手一指乾坤颠，便送五人上了阎王殿。",
	["tid#legend_talk_90201"]="且慢！！！",
	["tid#legend_talk_90202"]="腾腾腾，五个贼子应声倒！原是那东海大侠的剑气生。",
	["tid#legend_talk_90301"]="且慢！！！",
	["tid#legend_talk_90302"]="大侠如此如此这么着，打得那贼人叫嗷嗷！",
	["tid#legend_talk_90401"]="且慢！！！",
	["tid#legend_talk_90402"]="虽说宵小计谋刁，不敌大侠本事高，哐哐几下人没了，还让了贼人两三招。",
	["tid#legend_talk_90501"]="且慢！！！",
	["tid#legend_talk_90502"]="先前那乱战不觉间，已将百人震退倒路边。",
	["tid#legend_talk_90601"]="且慢！！！",
	["tid#legend_talk_90602"]="走过三川六河大海大江，上哪寻得这样的大侠英勇威武又举世无双~",
	["tid#legend_talk_90701"]="且慢！！！",
	["tid#legend_talk_90702"]="大侠低头脚下看，百名贼人已投降。",
	["tid#legend_talk_90801"]="且慢！！！",
	["tid#legend_talk_90802"]="大侠们个个是打遍四海无敌手，百来个小贼喽啰净是白饶。",
	["tid#legend_talk_90901"]="且慢！！！",
	["tid#legend_talk_90902"]="只见这刀来剑往战火急，大侠早已坚持五十息！",
	["tid#legend_talk_91001"]="且慢！！！",
	["tid#legend_talk_91002"]="大侠志若磐石气自烈，不觉间燃起的焚香已半截。",
	["tid#legend_talk_91101"]="且慢！！！",
	["tid#legend_talk_91102"]="大侠愈战愈勇中气正，遥听更漏滴了六十声。",
	["tid#legend_talk_91201"]="且慢！！！",
	["tid#legend_talk_91202"]="贼人的来势气汹汹，大侠的武功也武勇，从日出战到了日上三竿头。",
	["tid#limit_1"]="今日次数已达到上限",
	["tid#limit_2"]="今日次数",
