	["tid#mining_dec_03"]="珍品矿洞，稀有掉落概率提高50%",
	["tid#mining_dec_02"]="极品矿洞，稀有掉落概率提高100%",
	["tid#mining_dec_01"]="1.苗疆分为4个区域，每个区域仅可使用对应的侠客战斗，且每个区域仅可占领1个觅宝点，已占领觅宝点依然可以发起攻击，胜利后会驱逐对应位置的玩家；\\n\\n2.点击觅宝点即可挑战对应的位置驻守的玩家，胜利后即可占领觅宝点。占领后，觅宝点随着时间产生收益，具体收益可通过觅宝点界面查看；\\n\\n3.觅宝点收益分为两部分，一部分为固定收益随时间产生，一部分为随机收益，挂机中有几率产生，时间越久几率越大。珍品与极品觅宝点会掉落更高级道具，且几率更高；\\n\\n4.觅宝点收益最多保留12小时（随阿闲好感度等级提升，最大24小时），超时后会自动撤离，奖励保存在【觅宝点】界面；\\n\\n5.新占领的觅宝点会存在保护时间，1级区域保护时间为6小时，2级区域保护时间为3小时，3级区域保护时间为2小时，4级区域保护时间为1小时，5级区域保护时间为30分钟；\\n\\n6.同帮会成员在同一线路会触发攻击力加成，3人时为5%攻击力，6人时为10%攻击力；\\n\\n7.每周前50个小时为双倍收益，第50-100小时为正常收益，100小时后收益减半。收益按照分钟结算，计算双倍时间的收益后，小数点向下取整。\\n\\n8.占领时长未满4小时，主动撤退后1小时内无法进攻相同觅宝点",
