	["tid#mining_location2_shui_5"]="万岛归墟(跨服)",
	["tid#mining_dec_04"]="里程碑奖励",
	["tid#mining_dec_05"]="1.苗疆觅宝4个区域每周共有50小时的双倍收益时间，区域之间双倍时间不互相影响。\\n\\n2.双倍时间使用完毕后，将回归50小时正常收益。正常收益使用完毕后，苗疆将处于过度开采状态，收益减半。\\n\\n3.苗疆里程碑奖励将随着玩家在4个区域开采时间增长，每个区域的开采都会累计。",
	["tid#TianJiSai_des_1"]="恭喜少侠成功晋升五行地赛前100名，本周日晚上0点五行地赛重置时，仍旧处于前100名的玩家将获得“五行天赛”的参赛资格",
	["tid#TianJiSai_des_2"]="恭喜少侠成功晋升五行地赛前20名，本周日晚上0点五行地赛重置时，仍旧处于前20名的玩家将获得“五行天赛”的参赛资格",
	["tid#TianJiSai_des_3"]="您已晋升五行天赛，无法再次挑战五行地赛",
	["tid#TianJiSai_des_4"]="很遗憾，您未获得五行天赛的参赛资格",
	["tid#TianJiSai_des_5"]="五行天赛阵容说明文本",
	["tid#TianJiSai_des_6"]="1.五行天赛每周为一轮，每轮结束时根据结算时的排名发放奖励，并重置积分；\\n\\n2.每轮将选定三个势力为本周参赛势力，本轮中只能使用这三个势力的侠客进行挑战和防守\\n\\n3.五行天赛中的战斗将采用2v2模式，每个玩家需要配置两个队伍分别进行对战，每支队伍都有独有的参赛势力\\n\\n4.开启新一轮后必须进入一次擂台才能获得初期积分并获得排名，初期积分会根据上轮成绩而有不同\\n\\n5.挑战他人，胜者积分提高，败者积分下降\\n\\n6.每天有免费挑战的机会，免费次数用尽后可以使用元宝购买次数\\n\\n7.每天晚上24时根据当时排名发放每日奖励。\\n\\n8.每轮结束时，五行天赛排行榜中后20名的玩家将会退回到五行地赛，并从五行地赛排行榜中挑选前20名的玩家补位到五行天赛\\n\\n9.天机赛战斗判定胜负时，首先要判断胜场数量，胜场数量多的玩家获得对战的胜利；当胜场数量相同时，存活侠客数量多的玩家获得胜利；存活侠客数量也相同时，剩余血量多的玩家获得胜利；剩余血量也相同时，战斗力较高的玩家获得胜利",
	["tid#TianJiSai_des_7"]="请注意，本轮结束时，五行天赛排行榜后20名的玩家将退回五行地赛，请少侠努力保持排名",
	["tid#LianSai_des_1"]="恭喜少侠成功晋升五行天赛前10名，本周日晚上0点五行天赛重置时，仍旧处于前10名的玩家将获得“五行联赛”的参赛资格",
	["tid#LianSai_des_2"]="恭喜少侠成功晋升五行天赛前10名，本周日晚上0点五行天赛重置时，仍旧处于前10名的玩家将获得“五行联赛”的参赛资格",
	["tid#LianSai_des_3"]="您已晋升五行联赛，无法再次挑战五行地赛",
	["tid#LianSai_des_4"]="很遗憾，您未获得五行联赛的参赛资格",
	["tid#LianSai_des_5"]="五行联赛阵容说明文本",
	["tid#LianSai_des_6"]="1.五行联赛每周为一轮，每轮结束时根据结算时的排名发放奖励，并重置积分；\\n\\n2.五行联赛开启时，每个服务器中五行天赛排名前25名的玩家将获得参赛资格；\\n\\n3.获得五行联赛参赛资格的玩家仍旧可以进入五行天赛；\\n\\n4.五行联赛中的战斗将采用3v3模式，每个玩家需要配置三个队伍分别进行对战，每支队伍都有独有的参赛势力；\\n\\n5.开启新一轮后必须进入一次擂台才能获得初期积分并获得排名；\\n\\n6.挑战他人，胜者积分提高，败者积分下降；\\n\\n7.每天有免费挑战的机会，免费次数用尽后可以使用元宝购买次数，该次数会与五行地赛、五行天赛共用；\\n\\n8.每天晚上24点根据当时排名发放每日奖励；\\n\\n9.五行联赛战斗判定胜负时，首先要判断胜场数量，胜场数量多的玩家获得对战的胜利；当胜场数量相同时，存活侠客数量多的玩家获得胜利；存活侠客数量也相同时，剩余血量多的玩家获得胜利；剩余血量也相同时，战斗力较高的玩家获得胜利；",
	["tid#LianSai_des_7"]="请注意，本轮结束时，五行联赛排行榜后20名的玩家将退回五行地赛，请少侠努力保持排名",
