	["tid#NfourtowerDes_1"]="四象守卫",
	["tid#NfourtowerDes_2"]="精英守卫",
	["tid#NfourtowerDes_3"]="四象首领",
	["tid#NfourtowerDes_4"]="打开后可随机获得一个奇物",
	["tid#NfourtowerDes_5"]="打开后可获得少量奖励",
	["tid#NfourtowerDes_6"]="打开后可获得中量奖励",
	["tid#NfourtowerDes_7"]="打开后可获得大量奖励",
	["tid#NfourtowerDes_8"]="1.四象阵每周刷新，每次刷新时会发放20次挑战次数；\\n\\n2.除消耗元宝开启的宝箱以外，玩家在四象阵中开启宝箱、挑战敌人成功后都会消耗一次挑战次数；\\n\\n3.四象阵中会随机出现2~4个敌人或者宝箱，玩家只能选择其中一个挑战或开启；\\n\\n4.不同敌人携带的真气和奇物奖励不相同，且奇物只能在四象阵中生效；\\n\\n5.等级越高的敌人，携带的奖励也会越多，奇物也会越好；\\n\\n6.在四象阵中每击败一个四象守卫，下次刷新的敌人等级便会提升；击败敌人的等级越高，敌人提升的等级也会越高，请谨慎权衡奖励和难度；\\n\\n7.提高特权等级可以获得额外的挑战次数；\\n\\n8.每周末四象阵重置时，会清除玩家获得的所有奇物，并相应的降低难度等级；",
	["tid#NfourtowerDes_9"]="放弃当前宝箱奖励，继续向前挑战",
