	["tid#TitleDes_10010"]="获得此称号后，可在头像处使用，重复获得转化为500元宝。",
	["tid#TitleDes_10011"]="获得此称号后，可在头像处使用，重复获得转化为2000元宝。",
	["tid#TitleDes_10012"]="获得此称号后，可在头像处使用，重复获得可升级，称号满级后再次获得可转化为2000元宝。",
	["tid#TianXiaDes_01"]="1.帮会争锋榜分为本服榜和跨服榜两个\n\n2.本服榜中只会展示本服帮会的积分排行，且不随大赛季结束重置；\n\n3.跨服榜中会展示当前跨服组中所有帮会的积分排行，大赛季结束时，帮会积分和排行榜会重置\n",
	["tid#TianXiaDes_02"]="1.苗疆积分榜分为本服榜和跨服榜两个\n\n2.本服榜中只会展示本服玩家的苗疆积分排行，且不随大赛季结束重置；\n\n3.跨服榜中会展示当前跨服组中所有玩家的苗疆积分排行，大赛季结束时，苗疆积分和排行榜会重置\n\n4.当玩家占领苗疆探宝跨服区域的矿点后，该矿点会随时间产出苗疆积分；\n\n5.苗疆积分会在领取矿点奖励时发放给玩家\n\n\n6.占领难度越高的矿点，产出的积分也会越多",
	["tid#TianXiaDes_03"]="1.天下演武榜分为本服榜和跨服榜两个\n\n2.本服榜中只会展示本服玩家的段位积分排行；\n\n3.跨服榜中会展示当前跨服组中所有玩家的段位积分排行；\n\n4.巅峰论剑开启时，会从天下演武跨服榜中选取排名靠前的玩家参加；",
	["tid#TianXiaDes_04"]="1.武林绝学榜分为本服榜和跨服榜两个\n\n2.本服榜中只会展示本服玩家的秘籍积分排行；\n\n3.跨服榜中会展示当前跨服组中所有玩家的秘籍积分排行；\n\n4.秘籍积分为玩家身上和背包中所有秘籍的评分之和；",
	["tid#TianXiaDes_05"]="1.神兵利器榜分为本服榜和跨服榜两个\n\n2.本服榜中只会展示本服玩家的装备战力排行；\n\n3.跨服榜中会展示当前跨服组中所有玩家的装备战力排行；\n\n4.排名时，会将玩家背包和身上所有的装备战力相加并进行排名；",
	["tid#TianXiaDes_06"]="1.上古遗物榜分为本服榜和跨服榜两个\n\n2.本服榜中只会展示本服玩家的法宝等级排行；\n\n3.跨服榜中会展示当前跨服组中所有玩家的法宝等级排行；\n\n4.上古遗物榜中会记录玩家法宝的历史最高等级；",
	["tid#TianXiaDes_07"]="1.两仪相晖榜的分数由少侠拥有的所有阴阳侠客属性及其品质决定，\n\n2。其中紫品90分，紫品1星180分；\n橙品360分，橙品1星650分，橙品2星900分；\n红品1260分，红品1星1620分，红品2星1980分，红品3星2340分；\n白品2700分，白品1星3060分，白品2星3420分，白品3星3780分，白品4星4140分\n彩品4500分，彩品1星4860分，彩品2星5220分，彩品3星5580分，彩品4星5940分，彩品5星6300分",
	["tid#TianXiaMainDes_01"]="1.九州风云榜分为本服榜和跨服榜两个；\n\n2.本服榜中仅展示本服玩家的排名信息；\n\n3.跨服榜中会展示当前跨服组的所有玩家的排名信息；",
	["tid#Rename_01"]="请输入您的大名",
	["tid#KingsoftDes_01"]="金山游侠使用说明：\n1.金山游侠可以修改游戏中部分货币和道具，具体修改内容需要玩家自行探索；\n\n2.修改道具/货币时，需要在金山游侠主界面中填入当前道具/货币的数量，系统会自动搜索与数量相匹配的数据；\n\n3.当前一次搜索的道具/货币，数量发生改变时，可以输入改变后的数量再次搜索，若输入正确，则数据的条目会减少；\n\n4.每重复搜索同一个道具/货币成功一次，数据的条目数都会减少，若中途输入的数量错误，则数据条目会回到初始数量；\n\n5.点击搜索栏中的数据时，该数据会进入下方修改栏，点击修改栏中的数据时，会弹出修改弹窗；\n\n6.修改弹窗中会显示当前道具/货币可以修改的范围，若超过修改范围，则会弹出警告，请少侠谨慎操作；\n\n7.每种道具/货币在一期活动中仅可修改一次；\n\n8.可以修改的货币和道具类型会随着活动时间逐步解锁；",
	["tid#KingsoftDes_02"]="金山游侠-武林内置版",
	["tid#KingsoftDes_03"]="技术支持：阿闲办事处",
	["tid#KingsoftDes_04"]="官方网站：三达不溜点阿闲最可爱点康姆",
	["tid#KingsoftDes_05"]="阿闲软件股份有限公司版权所有",
	["tid#kingsoft_talk_001"]="学武之人，最忌就是贪心！少侠还是少拿点奖励吧！",
	["tid#kingsoft_talk_002"]="以少侠如今的火候，想要学会这一招还为时尚早啊……",
	["tid#kingsoft_talk_003"]="少侠，在下的时代已经过去了，需要帮助的话，不如去找那个名叫“阿闲”的后辈吧！",
	["tid#kingsoft_talk_004"]="到了在下这把年纪，想要再做出改变，也是为时已晚了，少侠还是放弃吧……",
	["tid#kingsoft_talk_005"]="时光荏苒，沧海桑田，原来的百宝箱现在也不过是一堆破铜烂铁了，还是不给少侠献丑了……",
